INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(1, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Persekutuan Tanah Melayu dan Bapa Kemerdekaan.', 'Meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia.', 'tunku_abdul_rahman.png'),
(5, 'Tun Abdul Razak bin Dato\' Hussein', 'Timbalan Perdana Menteri Persekutuan Tanah Melayu dan Pengerusi JAK.', 'Merangka hak perlembagaan dan perlindungan khas bagi Sabah dan Sarawak.', 'tun_abdul_razak.png'),
(41, 'Tun V.T. Sambanthan', 'Pemimpin MIC dan menteri dalam kerajaan Perikatan yang berjalan dari kampung ke ladang dan bandar untuk mendengar rakyat.', 'Menyokong usaha memupuk perpaduan antara kaum selepas peristiwa 13 Mei 1969.', 'tun_vt_sambanthan.png'),
(42, 'Pegawai MAGERAN', 'Pegawai berseragam yang bertugas semasa MAGERAN mentadbir negara selepas 1969.', 'Mewakili pegawai yang menjaga ketenteraman dan membantu pemulihan negara.', 'mageran_officer.png'),
(43, 'Pegawai Kanan MAGERAN', 'Pegawai kanan yang menyusun dokumen dan jadual kerja semasa MAGERAN (watak rekaan).', 'Mewakili penjawat awam yang membantu urusan pentadbiran selepas 13 Mei 1969.', 'pengarah_mageran.png'),
(44, 'Tauke Lim', 'Peniaga rumah kedai di bandar yang ramah dan suka berjenaka (watak rekaan).', 'Mewakili masyarakat Cina bandar yang berniaga dan melombong.', 'peniaga_rumah_kedai.png'),
(45, 'Pak Tani', 'Pesawah di kampung yang menanam padi untuk keperluan keluarga (watak rekaan).', 'Mewakili masyarakat Melayu kampung dengan pertanian sara diri.', 'petani_lama.png'),
(46, 'Pak Muthu', 'Pekerja ladang getah yang menoreh sebelum matahari naik (watak rekaan).', 'Mewakili masyarakat India yang bekerja dan tinggal di ladang.', 'penoreh_getah_lama.png'),
(47, 'Wei Jie', 'Pemuda Cina yang bersemangat menjadi sukarelawan (watak rekaan).', 'Mewakili anak muda Cina yang mahu membantu jiran berbilang kaum.', 'lengchai_cina.png'),
(49, 'Arun', 'Pemuda India yang suka bertanya dan berjenaka (watak rekaan).', 'Mewakili anak muda India yang ingin memahami prinsip bersama.', 'jejaka_india.png'),
(50, 'Hafiz', 'Pemuda Melayu yang peramah dan ingin tahu (watak rekaan).', 'Mewakili anak muda Melayu yang belajar menghormati kepelbagaian.', 'jejaka_melayu.png'),
(52, 'Murid Sekolah', 'Murid sekolah yang bertenaga dan gemar bertanya (watak rekaan).', 'Mewakili generasi muda yang mewarisi Rukun Negara.', 'budak_gajet.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(301, 'Arahan dari Bilik Gerakan', 3, 'Masuki peranan Tun Abdul Razak, Pengarah MAGERAN. Selepas 13 Mei 1969 kau menenangkan negara, mencari punca perpecahan, menubuhkan MAPEN dan merangka Rukun Negara hingga ia diisytiharkan pada 31 Ogos 1970.'),
(302, 'Pintu Rumah Rakyat', 3, 'Masuki peranan Tun V. T. Sambanthan, wakil rakyat yang mengetuk pintu rumah dan mendengar suara semua kaum. Daripada punca rusuhan hingga lima prinsip dan enam peranan, ceritakan Rukun Negara dari sisi rakyat biasa.'),
(303, 'Ikrar Satu Malaysia', 3, 'Masuki peranan Tunku Abdul Rahman pada hari Rukun Negara diisytiharkan. Ikuti tarikh, wakil, matlamat, prinsip dan peranan yang menjadikan ikrar itu pegangan seluruh rakyat Malaysia.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e3_n1_s1', 'Mei 1969, Kuala Lumpur. Jalan lengang dan berkawal. Di bilik gerakan, sebuah papan tanda baharu dipasang dan pegawai berbisik cemas tentang rusuhan yang baru berlaku.', 1, 301, 'peristiwa_13mei1969.png'),
('e3_n1_s2', 'Zaman British. Peta lama terbentang di atas meja. Tiga kawasan ditanda, iaitu sawah, lombong dan ladang. Pegawai Kanan memberitahu punca perpecahan bermula daripada cara orang mencari rezeki.', 2, 301, 'petempatan_semua_dahulu.png'),
('e3_n1_s3', 'Petang di pinggir pekan. Dari menara kawalan MAGERAN, Razak melihat tiga petempatan yang berasingan, kampung di pedalaman, rumah kedai di bandar dan rumah ladang di tepi getah.', 3, 301, 'petempatan_semua_dahulu.png'),
('e3_n1_s4', 'Awal 1970, bilik mesyuarat besar. Kerusi disusun mengelilingi meja panjang. Wakil dari pelbagai bidang tiba satu persatu, iaitu kerajaan negeri, parti politik, kumpulan agama, guru, akhbar, kesatuan sekerja dan majikan.', 4, 301, 'bilik_mesyuarat_formal.png'),
('e3_n1_s5', 'Dewan jawatankuasa. Lima helai kertas besar dilekatkan di dinding, setiap satu tertulis satu cita-cita. Wakil rakyat bertanya apakah makna sebenar setiap satu.', 5, 301, 'matlamat_rukun_negara_dahulu.png'),
('e3_n1_s6', '31 Ogos 1970, bangunan perlembagaan. Bendera dikibarkan dan tetamu penuh. Seorang pegawai membawa kad-kad peristiwa yang tersusun salah.', 6, 301, 'bangunan_perlembagaan.png'),
('e3_n1_s7', 'Hari-hari awal selepas pengisytiharan. Di jalan, masjid, kuil, gereja dan tokong berdiri berdekatan. Seorang guru membawa murid bertanya tentang dua prinsip pertama.', 7, 301, 'tempat_beribadat_semua.png'),
('e3_n1_s8', 'Di dalam mahkamah dan Parlimen, dua dokumen penting berada di meja. Pegawai muda ingin tahu perbezaan antara Perlembagaan dan undang-undang biasa.', 8, 301, 'bangunan_perlembagaan.png'),
('e3_n1_s9', 'Di dewan sekolah, lima situasi harian ditampal di papan. Murid diminta memadankan setiap situasi dengan satu prinsip Rukun Negara.', 9, 301, 'prinsip_rukun_negara_.png'),
('e3_n1_s10', 'Hari Kebangsaan. Jalur Gemilang berkibar, lagu Negaraku berkumandang, dan penduduk pelbagai agama berdiri bersama di dataran.', 10, 301, 'laungan_di_stadium_merdeka.png'),
('e3_n1_s11', 'Bandar sibuk. Poster kempen Anak Muda Bebas Dadah, pasar yang dikunjungi pelbagai kaum dan papan tanda trafik kelihatan di sekeliling.', 11, 301, 'bandar.png'),
('e3_n1_s12', 'Bilik mesyuarat moden pada hari penutup. Enam panel di dinding menunjukkan enam peranan Rukun Negara. Guru dan murid menunggu rumusan Razak.', 12, 301, 'bilik_mesyuarat_modern.png'),
('e3_n2_s1', 'Sebelum 1969, tiga petempatan di pinggir pekan, kampung, rumah kedai dan rumah ladang. Sambanthan berjalan dari pintu ke pintu bersama Pegawai MAGERAN.', 1, 302, 'petempatan_semua_dahulu.png'),
('e3_n2_s2', 'Malam 13 Mei 1969. Sambanthan membaca laporan dengan tangan menggeletar. Di luar tingkap, bunyi sirene kedengaran dari jauh.', 2, 302, 'peristiwa_13mei1969.png'),
('e3_n2_s3', 'Bilik mesyuarat MAPEN. Wakil duduk berderet, meja dipenuhi dokumen. Seorang setiausaha mencari dokumen yang betul untuk dibaca dalam mesyuarat.', 3, 302, 'bilik_mesyuarat_formal.png'),
('e3_n2_s4', 'Dewan awam. Lima poster matlamat Rukun Negara digantung. Orang ramai bertanya satu persatu maksud setiap matlamat.', 4, 302, 'matlamat_rukun_negara.png'),
('e3_n2_s5', '31 Ogos 1970. Yang di-Pertuan Agong Keempat membaca pengisytiharan di hadapan Perlembagaan. Orang ramai menanti dengan senyap.', 5, 302, 'bangunan_perlembagaan.png'),
('e3_n2_s6', 'Dewan sekolah. Lima kad prinsip diletakkan di atas meja panjang. Guru meminta murid memadankan setiap prinsip dengan maksudnya.', 6, 302, 'prinsip_rukun_negara_.png'),
('e3_n2_s7', 'Kawasan rumah ibadat berdekatan, iaitu masjid, kuil, gereja dan tokong. Penduduk pelbagai kaum berjalan bersama pada hari perayaan.', 7, 302, 'tempat_beribadat_semua.png'),
('e3_n2_s8', 'Bandar yang meriah. Papan tanda trafik, poster kempen dan kedai pelbagai kaum kelihatan di sekeliling. Sambanthan memerhati dengan bangga.', 8, 302, 'bandar.png'),
('e3_n2_s9', 'Bilik mesyuarat moden. Satu panel besar memaparkan dua peranan terakhir, iaitu nilai murni dan jati diri. Murid sekolah menanti rumusan Sambanthan.', 9, 302, 'bilik_mesyuarat_modern.png'),
('e3_n3_s1', 'Kuala Lumpur, 1969. Pegawai membawa laporan yang disusun mengikut tiga sebab. Tunku membacanya dengan wajah berat.', 1, 303, 'peristiwa_13mei1969.png'),
('e3_n3_s2', 'Bilik mesyuarat MAPEN. Wakil dari pelbagai latar duduk mengelilingi meja. Pegawai muda menyusun kad tarikh di hadapan Tunku.', 2, 303, 'bilik_mesyuarat_formal.png'),
('e3_n3_s3', '31 Ogos 1970. Tunku berdiri di tengah kerumunan. Yang di-Pertuan Agong Keempat membaca pengisytiharan.', 3, 303, 'bangunan_perlembagaan.png'),
('e3_n3_s4', 'Papan besar menyenaraikan lima matlamat. Tunku menunjuk satu persatu kepada murid yang berkumpul di dewan.', 4, 303, 'matlamat_rukun_negara_dahulu.png'),
('e3_n3_s5', 'Lima tiang menyokong bumbung sebuah pondok. Pada setiap tiang tertulis satu prinsip. Tunku berjalan di antaranya bersama murid.', 5, 303, 'prinsip_rukun_negara_.png'),
('e3_n3_s6', 'Hari perayaan. Penduduk pelbagai kaum mengunjungi rumah ibadat dan berkongsi juadah. Tunku memerhati bersama Pak Tani dan Tauke Lim.', 6, 303, 'tempat_beribadat_semua.png'),
('e3_n3_s7', 'Bandar sibuk dengan pasar dan kedai pelbagai kaum. Tunku bertemu sekumpulan belia yang menyertai kempen kesedaran undang-undang.', 7, 303, 'bandar.png'),
('e3_n3_s8', 'Hari penutup. Bilik mesyuarat dipenuhi murid, guru dan wakil. Tunku menyampaikan ucapan terakhirnya tentang Rukun Negara.', 8, 303, 'bilik_mesyuarat_modern.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(301, 'e3_n1_s1', 'Papan Tanda di Bilik Gerakan', 'Baca nota dan tentukan badan yang mentadbir negara selepas rusuhan 13 Mei 1969.', '5', 'Mengetahui MAGERAN mentadbir negara selepas rusuhan kaum 13 Mei 1969.', '{"clueText": "Nota ringkas: Selepas rusuhan kaum 13 Mei 1969, pentadbiran negara diambil alih oleh sebuah badan khas dan Tun Abdul Razak menjadi pengarahnya.", "options": [{"text": "Majlis Gerakan Negara (MAGERAN)", "isCorrect": true}, {"text": "Majlis Perundingan Negara (MAPEN)", "isCorrect": false, "consequence": "MAPEN ditubuhkan kemudian untuk merangka Rukun Negara. Pegawai tersasar dan nota dikembalikan."}, {"text": "Parlimen Malaysia", "isCorrect": false, "consequence": "Parlimen tidak bersidang pada waktu itu. Rakyat keliru siapa yang bertanggungjawab."}, {"text": "Suruhanjaya Pilihan Raya", "isCorrect": false, "consequence": "Suruhanjaya itu tidak mentadbir negara. Pegawai terpaksa membetulkan nota."}], "aftermath": "Nota salah dibaca dan pentadbiran sementara tidak jelas. Rakyat bertanya siapa yang memerintah.", "turns": [{"after": 5, "options": [{"text": "Negara perlu ditenangkan dahulu sebelum pentadbiran biasa disambung.", "isCorrect": true, "reaction": "Pegawai Kanan mengangguk. Jawapan itu menenangkan pegawai dan rakyat."}, {"text": "Rakyat tidak perlu tahu sebabnya kerana semuanya sudah selesai.", "isCorrect": false, "reaction": "Rakyat makin curiga kerana tiada penjelasan."}, {"text": "Kerana kita mahu memegang kuasa lebih lama, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Akhbar menulis pentadbiran darurat disalah faham sebagai merampas kuasa."}], "clue": "Negara ditenangkan dahulu, punca dicari kemudian."}]}'),
(302, 'e3_n1_s2', 'Peta Kegiatan Ekonomi', 'Cari tiga bukti kegiatan ekonomi yang berbeza mengikut kaum.', '2', 'Memahami perbezaan kegiatan ekonomi sebagai sebab Rukun Negara diperkenalkan.', '{"bgImage": "../assets/gameAsset/background/petempatan_semua_dahulu.png", "hotspots": [{"name": "Sawah: orang Melayu bertani sara diri", "top": "52%", "left": "20%"}, {"name": "Lombong bijih timah dan rumah kedai: orang Cina melombong dan berniaga", "top": "70%", "left": "78%"}, {"name": "Ladang getah: orang India bekerja dalam perladangan", "top": "30%", "left": "55%"}], "aftermath": "Bukti tidak lengkap dan laporan kepada MAGERAN kabur. Pegawai meneka-neka sebab jurang ekonomi.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, kegiatan ekonomi berbeza menyebabkan jurang ekonomi dan kaum jarang bertemu.", "isCorrect": true, "reaction": "Pegawai Kanan menulis jawapan itu terus ke dalam laporan."}, {"text": "Semua kaum mempunyai kegiatan ekonomi yang sama, tetapi mereka tidak suka bertemu.", "isCorrect": false, "reaction": "Pak Tani menggeleng. Itu tidak betul, kerana kerja kami memang berbeza."}, {"text": "Kegiatan ekonomi tidak ada kaitan dengan perpecahan kaum, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Pegawai Kanan menarik kembali fail itu. Hubungan ekonomi dan perpecahan sudah jelas."}], "clue": "Kegiatan ekonomi berbeza membawa jurang ekonomi."}]}'),
(303, 'e3_n1_s3', 'Nota Tempat Tinggal Berasingan', 'Nyahkod nota dan pilih akibat tempat tinggal yang berasingan.', '5', 'Memahami pengasingan tempat tinggal menyebabkan kurang peluang berinteraksi, dan fahaman politik merenggangkan hubungan kaum.', '{"clueText": "Nota MAGERAN: Orang Melayu tinggal di kampung, orang Cina di bandar dan orang India di ladang. Akibatnya, hubungan antara kaum menjadi ____.", "options": [{"text": "Kurang peluang berinteraksi antara masyarakat", "isCorrect": true}, {"text": "Terlalu kerap berinteraksi sehingga bergaduh", "isCorrect": false, "consequence": "Mereka jarang bertemu, bukan terlalu kerap. Nota dibetulkan."}, {"text": "Semua kaum berkongsi satu kawasan petempatan", "isCorrect": false, "consequence": "Kawasan petempatan memang berasingan. Pegawai menggaru kepala."}, {"text": "Tiada kesan terhadap hubungan kaum", "isCorrect": false, "consequence": "Pegawai menarik balik kenyataan itu. Ketidakbertemuan mengundang curiga."}], "aftermath": "Akibat tersalah dicatat dan MAGERAN tersilap menganggarkan punca masalah.", "turns": [{"after": 7, "options": [{"text": "Pada pendapat aku, kita galakkan kaum bertemu dan bekerjasama melalui satu pegangan bersama.", "isCorrect": true, "reaction": "Tauke Lim tersenyum. Itulah yang rakyat harapkan."}, {"text": "Bagi aku, kita biarkan sahaja mereka berasingan supaya tidak bergaduh dan lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai Kanan membantah. Jarak itu yang menanam curiga."}, {"text": "Kita paksa semua kaum berpindah ke satu bandar, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Rakyat marah kerana dipaksa meninggalkan rumah."}], "clue": "Pertemuan dan pegangan bersama merapatkan kaum."}]}'),
(304, 'e3_n1_s4', 'Surat Jemputan Jawatankuasa', 'Serahkan surat jemputan yang betul kepada pegawai.', '3', 'Memahami MAPEN dianggotai 66 wakil dan Jawatankuasa Rukun Negara di bawahnya merangka Rukun Negara pada 4 Mac 1970.', '{"npcName": "Pegawai MAGERAN", "prompt": "Saya perlu menghantar surat jemputan Jawatankuasa Rukun Negara. Surat yang manakah?", "options": [{"text": "Jemputan Jawatankuasa Rukun Negara, 4 Mac 1970, MAPEN: 66 wakil", "item": "surat", "isCorrect": true}, {"text": "Jemputan Jawatankuasa Rukun Negara, 31 Ogos 1970, MAGERAN", "item": "surat", "isCorrect": false, "consequence": "Tarikh dan badan salah. Wakil tiba pada hari yang salah dan mesyuarat tertangguh."}, {"text": "Jemputan Suruhanjaya Cobbold, 17 Januari 1962", "item": "surat", "isCorrect": false, "consequence": "Itu surat Era Malaysia. Pegawai menyerahkannya kepada orang yang salah."}, {"text": "Jemputan Majlis Raja-Raja, 4 Mac 1970", "item": "surat", "isCorrect": false, "consequence": "Majlis itu bukan penggubal Rukun Negara. Wakil kebingungan."}], "aftermath": "Surat salah dihantar. Mesyuarat tertangguh dan rakyat bertanya mengapa ia lambat.", "turns": [{"after": 5, "options": [{"text": "Mereka datang dari pelbagai bidang supaya semua suara didengar.", "isCorrect": true, "reaction": "Sambanthan mengangguk. Itulah semangat permuafakatan."}, {"text": "Mereka dipilih oleh satu parti sahaja, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Wakil kumpulan lain tersinggung dan mahu keluar."}, {"text": "Pada pendapat aku, mereka dilantik untuk menyetujui apa sahaja yang MAGERAN mahu.", "isCorrect": false, "reaction": "Akhbar menulis jawatankuasa itu hanya cap getah. Kepercayaan menurun."}], "clue": "Wakil dari pelbagai pihak supaya semua didengar."}]}'),
(305, 'e3_n1_s5', 'Padanan Lima Matlamat', 'Padankan setiap matlamat dengan maksudnya.', '4', 'Mengenal lima matlamat Rukun Negara.', '{"pairs": [{"text": "Perpaduan lebih erat", "pair": 1}, {"text": "Hubungan erat dalam kalangan seluruh masyarakat", "pair": 1}, {"text": "Cara hidup demokrasi", "pair": 2}, {"text": "Memelihara cara hidup demokrasi", "pair": 2}, {"text": "Masyarakat adil", "pair": 3}, {"text": "Kemakmuran dinikmati secara adil dan saksama", "pair": 3}, {"text": "Cara liberal", "pair": 4}, {"text": "Terhadap tradisi kebudayaan yang kaya dan pelbagai corak", "pair": 4}, {"text": "Masyarakat progresif", "pair": 5}, {"text": "Menggunakan sains dan teknologi moden", "pair": 5}], "aftermath": "Padanan tersilap, dan wakil keliru tentang cita-cita negara.", "turns": [{"after": 5, "options": [{"text": "Sebenarnya, kerana matlamat memberi arah supaya semua kaum bergerak ke tujuan yang sama.", "isCorrect": true, "reaction": "Sambanthan mengangguk. Itulah tujuan persidangan ini."}, {"text": "Kerana matlamat hanya hiasan dalam teks Rukun Negara, jadi kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Wakil mula meragui kesungguhan jawatankuasa."}, {"text": "Kerana matlamat hanya untuk satu kaum, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Wakil kaum lain menarik diri. Perpaduan terjejas."}], "clue": "Matlamat memberi arah kepada semua kaum."}]}'),
(306, 'e3_n1_s6', 'Kad Peristiwa Rukun Negara', 'Susun peristiwa pembentukan Rukun Negara mengikut tarikh.', '1', 'Menyusun 13 Mei 1969, 4 Mac 1970 dan 31 Ogos 1970.', '{"timelineItems": [{"id": 1, "year": "13 Mei 1969", "text": "Rusuhan kaum dan MAGERAN mentadbir negara", "why": "Rusuhan itu mencetuskan keperluan menyatukan rakyat."}, {"id": 2, "year": "4 Mac 1970", "text": "Jawatankuasa Rukun Negara di bawah MAPEN merangka Rukun Negara", "why": "Perlu ada perundingan sebelum diisytiharkan."}, {"id": 3, "year": "31 Ogos 1970", "text": "Rukun Negara diisytiharkan oleh Yang di-Pertuan Agong Keempat", "why": "Selepas dirangka, barulah diisytiharkan."}], "aftermath": "Kad tersilap disusun. Rukun Negara kelihatan diisytiharkan sebelum dirangka.", "turns": [{"after": 5, "options": [{"text": "Kerana hari itu mengingatkan kita bahawa perpaduan ialah asas negara.", "isCorrect": true, "reaction": "Murid itu tersenyum. Jawapan itu mudah difahami."}, {"text": "Kerana tiada tarikh lain yang sesuai, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Murid keliru kerana jawapan itu tiada sebab."}, {"text": "Pada pendapat aku, kerana ia hari cuti yang panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Murid ketawa tetapi gurunya menggeleng kecewa."}], "clue": "Hari Kebangsaan menegaskan perpaduan."}]}'),
(307, 'e3_n1_s7', 'Kad Prinsip Pertama', 'Serahkan kad yang betul kepada murid.', '3', 'Mengetahui prinsip pertama ialah Kepercayaan kepada Tuhan dan prinsip kedua ialah Kesetiaan kepada Raja dan Negara.', '{"npcName": "Murid Sekolah", "prompt": "Saya perlu menyerahkan kad prinsip pertama Rukun Negara kepada guru. Yang mana satu?", "options": [{"text": "Kepercayaan kepada Tuhan", "item": "dokumen", "isCorrect": true}, {"text": "Kesetiaan kepada Raja dan Negara", "item": "dokumen", "isCorrect": false, "consequence": "Itu prinsip kedua. Guru mengerutkan dahi dan menyuruh murid mencuba lagi."}, {"text": "Keluhuran Perlembagaan", "item": "dokumen", "isCorrect": false, "consequence": "Itu prinsip ketiga. Susunan Rukun Negara menjadi kacau."}, {"text": "Kesopanan dan Kesusilaan", "item": "dokumen", "isCorrect": false, "consequence": "Itu prinsip kelima. Guru menggeleng."}], "aftermath": "Kad salah diserahkan dan susunan prinsip menjadi kacau di dalam kelas.", "turns": [{"after": 5, "options": [{"text": "Rasanya, kerana agama menyatukan masyarakat berbilang kaum dan menghormati amalan orang lain.", "isCorrect": true, "reaction": "Murid mengangguk. Dia faham kepentingan hormat-menghormati."}, {"text": "Kerana agama hanya untuk kaum tertentu sahaja, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai membetulkan: agama ialah pegangan utama semua rakyat Malaysia."}, {"text": "Sebenarnya, kerana agama tidak penting untuk perpaduan dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Murid keliru kerana jawapan itu bertentangan dengan prinsip pertama."}], "clue": "Agama dihormati supaya masyarakat bersatu."}]}'),
(308, 'e3_n1_s8', 'Bukti Prinsip Ketiga dan Keempat', 'Cari bukti Perlembagaan sebagai undang-undang tertinggi dan kepatuhan kepada undang-undang.', '2', 'Memahami Keluhuran Perlembagaan dan Kedaulatan Undang-undang.', '{"bgImage": "../assets/gameAsset/background/bangunan_perlembagaan.png", "hotspots": [{"name": "Buku Perlembagaan Persekutuan: undang-undang tertinggi negara", "top": "45%", "left": "30%"}, {"name": "Palu hakim di mahkamah: undang-undang mesti dipatuhi", "top": "65%", "left": "72%"}, {"name": "Papan notis undang-undang: rakyat mematuhi undang-undang", "top": "25%", "left": "60%"}], "aftermath": "Bukti tidak ditemui dan pegawai muda keliru tentang dua prinsip itu.", "turns": [{"after": 5, "options": [{"text": "Ya. Perlembagaan Persekutuan ialah undang-undang tertinggi negara.", "isCorrect": true, "reaction": "Arun mengangguk dan menulis jawapan itu di bukunya."}, {"text": "Tidak. Mana-mana institusi boleh mengatasi Perlembagaan.", "isCorrect": false, "reaction": "Pegawai menggeleng. Keluhuran Perlembagaan menolak pendapat itu."}, {"text": "Tidak penting, kerana rakyat tidak perlu mematuhinya dan lupakan sahaja.", "isCorrect": false, "reaction": "Arun terkejut. Prinsip itu menuntut rakyat mematuhinya."}], "clue": "Perlembagaan ialah undang-undang tertinggi."}]}'),
(309, 'e3_n1_s9', 'Situasi dan Prinsip', 'Padankan situasi dengan prinsip Rukun Negara.', '4', 'Menerapkan lima prinsip Rukun Negara dalam situasi harian.', '{"pairs": [{"text": "Mematuhi undang-undang jalan raya", "pair": 1}, {"text": "Kedaulatan undang-undang", "pair": 1}, {"text": "Memimpin nenek melintas jalan", "pair": 2}, {"text": "Kesopanan dan kesusilaan", "pair": 2}, {"text": "Menggubal undang-undang di Parlimen", "pair": 3}, {"text": "Keluhuran perlembagaan", "pair": 3}, {"text": "Berdoa mengikut kepercayaan masing-masing", "pair": 4}, {"text": "Kepercayaan kepada Tuhan", "pair": 4}, {"text": "Rela berkorban demi kedaulatan negara", "pair": 5}, {"text": "Kesetiaan kepada raja dan negara", "pair": 5}], "aftermath": "Padanan tersilap dan murid keliru menerapkan prinsip dalam kehidupan.", "turns": [{"after": 5, "options": [{"text": "Kesopanan ialah amalan nilai murni dalam hidup harian.", "isCorrect": true, "reaction": "Murid itu mengangguk. Dia kini tahu contoh dalam hidup sendiri."}, {"text": "Kesopanan hanya terpakai di sekolah, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Cikgu menggeleng. Nilai murni perlu diamalkan di mana-mana."}, {"text": "Kesopanan tidak perlu diamalkan kalau tiada sesiapa melihat.", "isCorrect": false, "reaction": "Murid keliru kerana nilai murni ialah keperibadian, bukan lakonan."}], "clue": "Kesopanan ialah nilai murni dalam hidup harian."}]}'),
(310, 'e3_n1_s10', 'Nota Peranan Rukun Negara', 'Nyahkod nota dan pilih peranan yang betul.', '5', 'Memahami Rukun Negara meraikan kepelbagaian agama dan membentuk masyarakat patriotik.', '{"clueText": "Nota: Rukun Negara berperanan membentuk rakyat yang patuh ajaran agama masing-masing dan menghormati lambang kedaulatan negara seperti Jalur Gemilang, Jata Negara dan lagu Negaraku.", "options": [{"text": "Meraikan kepelbagaian agama dan membentuk masyarakat patriotik", "isCorrect": true}, {"text": "Mengasingkan kaum mengikut agama", "isCorrect": false, "consequence": "Rukun Negara menyatukan, bukan mengasingkan. Hafiz mengerutkan dahi."}, {"text": "Membenarkan semua undang-undang diabaikan", "isCorrect": false, "consequence": "Peranan itu bercanggah dengan prinsip kedaulatan undang-undang."}, {"text": "Menggalakkan perbalahan antara kaum", "isCorrect": false, "consequence": "Itu bertentangan dengan matlamat perpaduan. Nota dikembalikan."}], "aftermath": "Nota tersalah baca dan Hafiz keliru tentang peranan Rukun Negara.", "turns": [{"after": 5, "options": [{"text": "Kerana semua agama dihormati dan semua rakyat menyayangi negara yang sama.", "isCorrect": true, "reaction": "Hafiz tersenyum. Itulah semangat patriotik dan toleransi."}, {"text": "Kerana jiran perlu menukar agama, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Hafiz terkejut. Rukun Negara menghormati agama masing-masing."}, {"text": "Menurut aku, kerana kita tidak perlu menghormati lambang negara dan biarkan sahaja.", "isCorrect": false, "reaction": "Orang ramai berpaling. Jalur Gemilang dan Negaraku ialah lambang kedaulatan."}], "clue": "Hormat agama dan sayang negara."}]}'),
(311, 'e3_n1_s11', 'Bukti Peranan di Bandar', 'Cari bukti penghormatan undang-undang dan perpaduan di bandar.', '2', 'Memahami Rukun Negara memupuk sikap menghormati undang-undang dan mengukuhkan perpaduan.', '{"bgImage": "../assets/gameAsset/background/bandar.png", "hotspots": [{"name": "Poster Kempen Anak Muda Bebas Dadah: patuh undang-undang", "top": "28%", "left": "22%"}, {"name": "Pasar yang dikunjungi pelbagai kaum: perpaduan masyarakat", "top": "62%", "left": "58%"}, {"name": "Papan tanda trafik: rakyat mematuhi undang-undang jalan raya", "top": "40%", "left": "80%"}], "aftermath": "Bukti tidak lengkap dan sukarelawan tidak dapat menerangkan peranan Rukun Negara.", "turns": [{"after": 5, "options": [{"text": "Kerana undang-undang menjamin keamanan dan kesejahteraan semua rakyat.", "isCorrect": true, "reaction": "Wei Jie mengangguk. Dia memahami kepentingan mematuhi undang-undang."}, {"text": "Kerana undang-undang hanya untuk orang yang tidak bijak, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Wei Jie menggeleng. Semua rakyat perlu mematuhinya."}, {"text": "Rasanya, kerana undang-undang boleh dilanggar jika tiada pegawai melihat.", "isCorrect": false, "reaction": "Tauke Lim membantah. Kedaulatan undang-undang menuntut kepatuhan setiap masa."}], "clue": "Undang-undang menjamin keamanan."}]}'),
(312, 'e3_n1_s12', 'Enam Peranan Rukun Negara', 'Padankan peranan Rukun Negara dengan maksudnya.', '4', 'Merumus enam peranan Rukun Negara: kepelbagaian agama, patriotik, hormat undang-undang, perpaduan, nilai murni dan jati diri.', '{"pairs": [{"text": "Meraikan kepelbagaian agama dan kepercayaan", "pair": 1}, {"text": "Menghormati amalan agama orang lain", "pair": 1}, {"text": "Masyarakat patriotik", "pair": 2}, {"text": "Menghormati bendera, Jata Negara dan lagu Negaraku", "pair": 2}, {"text": "Menghormati undang-undang", "pair": 3}, {"text": "Keamanan dan kesejahteraan terjamin", "pair": 3}, {"text": "Mengukuhkan perpaduan", "pair": 4}, {"text": "Permuafakatan dan toleransi", "pair": 4}, {"text": "Menerapkan nilai murni", "pair": 5}, {"text": "Hubungan harmoni dan saling menghormati", "pair": 5}, {"text": "Membentuk jati diri", "pair": 6}, {"text": "Rakyat berintegriti", "pair": 6}], "aftermath": "Padanan tersilap dan murid tidak dapat merumus peranan Rukun Negara.", "turns": [{"after": 7, "options": [{"text": "Rasanya, kerana jati diri yang berintegriti menjadikan kita jujur dan dipercayai.", "isCorrect": true, "reaction": "Murid mengangguk. Dia menulis ''jujur'' di buku catatannya."}, {"text": "Menurut aku, kerana jati diri bermaksud meniru orang lain dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Murid ketawa. Itu jauh daripada maksud jati diri."}, {"text": "Kerana integriti hanya penting semasa peperiksaan, kerana itu lebih mudah dan cepat.", "isCorrect": false, "reaction": "Guru menggeleng. Integriti perlu dalam semua bidang kehidupan."}], "clue": "Jati diri yang berintegriti dipercayai orang."}]}'),
(313, 'e3_n2_s1', 'Tiga Petempatan Berasingan', 'Cari tiga petempatan yang berasingan.', '2', 'Memahami pengasingan tempat tinggal: kampung, bandar, ladang.', '{"bgImage": "../assets/gameAsset/background/petempatan_semua_dahulu.png", "hotspots": [{"name": "Kampung di pedalaman: orang Melayu", "top": "55%", "left": "18%"}, {"name": "Rumah kedai di bandar: orang Cina", "top": "62%", "left": "68%"}, {"name": "Rumah ladang: orang India", "top": "30%", "left": "45%"}], "aftermath": "Peta tidak lengkap dan wakil rakyat tidak dapat menerangkan pengasingan petempatan.", "turns": [{"after": 5, "options": [{"text": "Mereka kurang berinteraksi kerana tempat tinggal berasingan.", "isCorrect": true, "reaction": "Pak Tani mengangguk dan tersenyum kepada Tauke Lim."}, {"text": "Mereka sering berinteraksi kerana tinggal berdekatan.", "isCorrect": false, "reaction": "Tauke Lim menggeleng. Rumah kami jauh antara satu sama lain."}, {"text": "Mereka tidak mahu berinteraksi kerana benci dan biarkan sahaja.", "isCorrect": false, "reaction": "Pak Muthu membantah. Bukan benci, tetapi tiada peluang."}], "clue": "Tempat tinggal berasingan, peluang bertemu sedikit."}]}'),
(314, 'e3_n2_s2', 'Ayat Terpadam', 'Nyahkod ayat terpadam dan pilih sebab ketiga.', '5', 'Mengenal perbezaan fahaman politik sebagai sebab ketiga.', '{"clueText": "Ayat laporan: Sebab ketiga ialah perbezaan ____ yang merenggangkan hubungan kaum sehingga mencetuskan rusuhan 13 Mei 1969.", "options": [{"text": "fahaman politik", "isCorrect": true}, {"text": "kegiatan ekonomi", "isCorrect": false, "consequence": "Itu sebab pertama. Laporan dikembalikan."}, {"text": "tempat tinggal", "isCorrect": false, "consequence": "Itu sebab kedua. Arun menggaru kepala."}, {"text": "jenis pakaian", "isCorrect": false, "consequence": "Itu tidak betul. Cuba ingat semula apa yang kita dengar tadi. Laporan menjadi kabur."}], "aftermath": "Laporan tidak dapat dibaca dan sebab ketiga tidak dicatat.", "turns": [{"after": 4, "options": [{"text": "Perbezaan fahaman politik merenggangkan hubungan kaum.", "isCorrect": true, "reaction": "Arun mengangguk. Dia kini faham mengapa politik perlu dipandu perpaduan."}, {"text": "Perbezaan fahaman politik mengeratkan hubungan kaum.", "isCorrect": false, "reaction": "Arun menggeleng. Kenyataan itu bercanggah dengan laporan."}, {"text": "Fahaman politik tiada kaitan dengan rusuhan, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai membetulkan: laporan menyebut kaitan jelas."}], "clue": "Fahaman politik merenggangkan hubungan kaum."}]}'),
(315, 'e3_n2_s3', 'Dokumen MAPEN', 'Serahkan dokumen yang betul kepada setiausaha.', '3', 'Mengetahui MAPEN 66 wakil dan Jawatankuasa Rukun Negara 4 Mac 1970.', '{"npcName": "Hafiz", "prompt": "Saya perlu membacakan dokumen penubuhan Jawatankuasa Rukun Negara. Yang mana satu?", "options": [{"text": "MAPEN, 66 wakil, Jawatankuasa Rukun Negara, 4 Mac 1970", "item": "dokumen", "isCorrect": true}, {"text": "MAGERAN, 13 Mei 1969, Rusuhan Kaum", "item": "dokumen", "isCorrect": false, "consequence": "Itu dokumen peristiwa rusuhan, bukan penubuhan jawatankuasa. Mesyuarat tersasar."}, {"text": "Suruhanjaya Cobbold, 1962, laporan Malaysia", "item": "dokumen", "isCorrect": false, "consequence": "Itu dokumen Era Malaysia. Wakil kebingungan."}, {"text": "Pengisytiharan Rukun Negara, 31 Ogos 1970", "item": "dokumen", "isCorrect": false, "consequence": "Itu pengisytiharan akhir, bukan penubuhan jawatankuasa."}], "aftermath": "Dokumen salah dibaca dan mesyuarat terpaksa diulang.", "turns": [{"after": 4, "options": [{"text": "Wakil daripada pelbagai pihak supaya semua suara didengar.", "isCorrect": true, "reaction": "Hafiz tersenyum. Itulah maksud perundingan."}, {"text": "Aku fikir wakil hanya satu kaum supaya mudah bersetuju.", "isCorrect": false, "reaction": "Wakil kaum lain membantah. Perundingan tidak adil."}, {"text": "Wakil tidak perlu bersuara kerana MAGERAN akan memutuskan.", "isCorrect": false, "reaction": "Hafiz membantah. Majlis itu dipanggil majlis perundingan."}], "clue": "Wakil pelbagai pihak supaya semua didengar."}]}'),
(316, 'e3_n2_s4', 'Matlamat dan Contoh', 'Padankan matlamat dengan contohnya.', '4', 'Mengenal lima matlamat Rukun Negara melalui contoh.', '{"pairs": [{"text": "Perpaduan lebih erat", "pair": 1}, {"text": "Kaum bertegur sapa dan bekerjasama", "pair": 1}, {"text": "Cara hidup demokrasi", "pair": 2}, {"text": "Rakyat mengundi memilih wakil", "pair": 2}, {"text": "Masyarakat adil", "pair": 3}, {"text": "Kemakmuran dinikmati secara adil dan saksama", "pair": 3}, {"text": "Cara liberal", "pair": 4}, {"text": "Menghormati tradisi kebudayaan yang pelbagai corak", "pair": 4}, {"text": "Masyarakat progresif", "pair": 5}, {"text": "Menggunakan sains dan teknologi moden", "pair": 5}], "aftermath": "Padanan tersilap dan orang ramai keliru tentang matlamat.", "turns": [{"after": 6, "options": [{"text": "Masyarakat adil bermakna kemakmuran dinikmati secara adil dan saksama.", "isCorrect": true, "reaction": "Wei Jie mengangguk. Itulah tafsiran yang tepat."}, {"text": "Aku fikir masyarakat adil bermakna hanya satu kaum yang makmur.", "isCorrect": false, "reaction": "Orang ramai membantah. Itu bukan keadilan."}, {"text": "Bagi aku, masyarakat adil bermakna tiada kemakmuran, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Wei Jie menggeleng. Matlamat itu mahukan kemakmuran dikongsi."}], "clue": "Kemakmuran dikongsi secara adil."}]}'),
(317, 'e3_n2_s5', 'Kad Pengisytiharan', 'Serahkan kad yang betul kepada pegawai istana.', '3', 'Mengetahui pengisytiharan 31 Ogos 1970 oleh Yang di-Pertuan Agong Keempat.', '{"npcName": "Pegawai MAGERAN", "prompt": "Saya perlu menyerahkan kad pengisytiharan kepada istana. Kad yang manakah?", "options": [{"text": "31 Ogos 1970, Yang di-Pertuan Agong Keempat", "item": "dokumen", "isCorrect": true}, {"text": "4 Mac 1970, Yang di-Pertuan Agong Pertama", "item": "dokumen", "isCorrect": false, "consequence": "Tarikh dan nama salah. Pegawai istana mengerutkan dahi."}, {"text": "31 Ogos 1957, Perdana Menteri", "item": "dokumen", "isCorrect": false, "consequence": "Itu tarikh kemerdekaan. Majlis bertukar kelam-kabut."}, {"text": "16 September 1963, Tunku Abdul Rahman", "item": "dokumen", "isCorrect": false, "consequence": "Itu tarikh Malaysia. Pegawai istana kebingungan."}], "aftermath": "Kad salah diserahkan dan majlis tertangguh.", "turns": [{"after": 4, "options": [{"text": "Kerana Hari Kebangsaan mengingatkan kita bahawa perpaduan ialah asas negara.", "isCorrect": true, "reaction": "Murid mengangguk dan tersenyum."}, {"text": "Kerana tiada tarikh lain yang sesuai, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Murid keliru kerana jawapan itu tiada sebab."}, {"text": "Pada pendapat aku, kerana ia hari cuti yang panjang dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Guru menggeleng kecewa."}], "clue": "Hari Kebangsaan menegaskan perpaduan."}]}'),
(318, 'e3_n2_s6', 'Padanan Lima Prinsip', 'Padankan prinsip dengan maksudnya.', '4', 'Mengenal lima prinsip Rukun Negara.', '{"pairs": [{"text": "Kepercayaan kepada Tuhan", "pair": 1}, {"text": "Agama pegangan utama dan hormat amalan beragama", "pair": 1}, {"text": "Kesetiaan kepada Raja dan Negara", "pair": 2}, {"text": "Taat setia kepada Yang di-Pertuan Agong", "pair": 2}, {"text": "Keluhuran Perlembagaan", "pair": 3}, {"text": "Perlembagaan undang-undang tertinggi negara", "pair": 3}, {"text": "Kedaulatan Undang-undang", "pair": 4}, {"text": "Hormati dan patuhi undang-undang", "pair": 4}, {"text": "Kesopanan dan Kesusilaan", "pair": 5}, {"text": "Amalan nilai murni keperibadian rakyat", "pair": 5}], "aftermath": "Padanan tersilap dan murid keliru dengan lima prinsip.", "turns": [{"after": 5, "options": [{"text": "Yang di-Pertuan Agong ialah Ketua Utama Negara.", "isCorrect": true, "reaction": "Murid mengangguk dan menulis jawapan itu."}, {"text": "Perdana Menteri ialah Ketua Utama Negara.", "isCorrect": false, "reaction": "Guru membetulkan: Perdana Menteri mengetuai kerajaan."}, {"text": "Ketua Hakim Negara ialah Ketua Utama Negara.", "isCorrect": false, "reaction": "Guru menggeleng. Ketua Hakim Negara mengetuai badan kehakiman."}], "clue": "Yang di-Pertuan Agong ialah Ketua Utama Negara."}]}'),
(319, 'e3_n2_s7', 'Bukti Peranan Agama dan Patriotik', 'Cari tiga bukti peranan Rukun Negara.', '2', 'Memahami peranan Rukun Negara dalam kepelbagaian agama dan semangat patriotik.', '{"bgImage": "../assets/gameAsset/background/tempat_beribadat_semua.png", "hotspots": [{"name": "Rumah ibadat pelbagai agama berdekatan: hormat kepelbagaian agama", "top": "45%", "left": "30%"}, {"name": "Jalur Gemilang berkibar: masyarakat patriotik", "top": "20%", "left": "60%"}, {"name": "Penduduk pelbagai kaum berjalan bersama: bertoleransi", "top": "70%", "left": "55%"}], "aftermath": "Bukti tidak lengkap dan Hafiz tidak dapat menerangkan peranan Rukun Negara.", "turns": [{"after": 4, "options": [{"text": "Rasanya, menghormati amalan agama orang lain dan menyayangi negara.", "isCorrect": true, "reaction": "Hafiz mengangguk gembira."}, {"text": "Sebenarnya, menukar agama jiran supaya sama dan itu lebih senang.", "isCorrect": false, "reaction": "Hafiz terkejut. Rukun Negara menghormati agama masing-masing."}, {"text": "Tidak peduli akan agama orang lain, jadi orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Hafiz menggeleng. Menghormati bukan membiarkan."}], "clue": "Hormat agama dan sayang negara."}]}'),
(320, 'e3_n2_s8', 'Nota Peranan Bandar', 'Nyahkod nota dan pilih peranan yang betul.', '5', 'Memahami Rukun Negara memupuk sikap menghormati undang-undang dan mengukuhkan perpaduan.', '{"clueText": "Nota: Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan, manakala permuafakatan dan toleransi ____.", "options": [{"text": "mengukuhkan perpaduan", "isCorrect": true}, {"text": "melemahkan perpaduan", "isCorrect": false, "consequence": "Itu bertentangan dengan peranan Rukun Negara."}, {"text": "menambah jenayah", "isCorrect": false, "consequence": "Itu tiada kaitan dengan toleransi."}, {"text": "mengasingkan kaum", "isCorrect": false, "consequence": "Itu bercanggah dengan perpaduan."}], "aftermath": "Nota tersalah baca dan Wei Jie keliru tentang peranan Rukun Negara.", "turns": [{"after": 4, "options": [{"text": "Menurut aku, menghormati undang-undang menjamin keamanan dan kesejahteraan.", "isCorrect": true, "reaction": "Wei Jie mengangguk. Dia kini faham maksud kedaulatan undang-undang."}, {"text": "Undang-undang hanya untuk pegawai kerajaan, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Tauke Lim menggeleng. Semua rakyat perlu mematuhinya."}, {"text": "Undang-undang boleh dilanggar jika mahu, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Wei Jie membantah. Itu merosakkan keamanan."}], "clue": "Undang-undang menjamin keamanan."}]}'),
(321, 'e3_n2_s9', 'Enam Peranan Rukun Negara', 'Padankan peranan dengan maksudnya.', '4', 'Merumus enam peranan Rukun Negara.', '{"pairs": [{"text": "Meraikan kepelbagaian agama", "pair": 1}, {"text": "Hormat amalan agama orang lain", "pair": 1}, {"text": "Masyarakat patriotik", "pair": 2}, {"text": "Hormat Jalur Gemilang, Jata Negara dan Negaraku", "pair": 2}, {"text": "Menghormati undang-undang", "pair": 3}, {"text": "Keamanan dan kesejahteraan", "pair": 3}, {"text": "Mengukuhkan perpaduan", "pair": 4}, {"text": "Permuafakatan dan toleransi", "pair": 4}, {"text": "Menerapkan nilai murni", "pair": 5}, {"text": "Hubungan harmoni dan saling menghormati", "pair": 5}, {"text": "Membentuk jati diri", "pair": 6}, {"text": "Kejujuran tulen: tidak meniru dalam peperiksaan", "pair": 6}], "aftermath": "Padanan tersilap dan murid tidak dapat merumus peranan.", "turns": [{"after": 6, "options": [{"text": "Integriti ialah kejujuran yang tulen dan tidak berubah.", "isCorrect": true, "reaction": "Murid mengangguk dan menulis jawapan itu."}, {"text": "Integriti ialah menipu apabila tidak dilihat, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Murid terkejut. Itu bertentangan dengan kejujuran."}, {"text": "Menurut aku, integriti hanya penting pada hari peperiksaan.", "isCorrect": false, "reaction": "Guru menggeleng. Integriti perlu setiap masa."}], "clue": "Integriti ialah kejujuran yang tulen."}]}'),
(322, 'e3_n3_s1', 'Sebab dan Perincian', 'Padankan sebab dengan perincian.', '4', 'Mengukuhkan tiga sebab pengenalan Rukun Negara.', '{"pairs": [{"text": "Perbezaan kegiatan ekonomi", "pair": 1}, {"text": "Melayu bertani, Cina berniaga, India di ladang", "pair": 1}, {"text": "Pengasingan tempat tinggal", "pair": 2}, {"text": "Kampung, bandar dan ladang berasingan", "pair": 2}, {"text": "Perbezaan fahaman politik", "pair": 3}, {"text": "Merenggangkan hubungan kaum", "pair": 3}], "aftermath": "Sebab dan perincian bercampur dan laporan sukar difahami.", "turns": [{"after": 5, "options": [{"text": "Sebenarnya, kita perlu satu pegangan bersama supaya semua kaum bersatu.", "isCorrect": true, "reaction": "Pegawai Kanan mengangguk. Itu yang rakyat harapkan."}, {"text": "Kita biarkan sahaja kaum berasingan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pegawai Kanan membantah. Itu menambah curiga."}, {"text": "Kita salahkan satu kaum, jadi cukup dibiarkan begitu sahaja dan biarkan sahaja.", "isCorrect": false, "reaction": "Tunku menggeleng. Menuding jari tidak menyelesaikan masalah."}], "clue": "Satu pegangan bersama menyatukan kaum."}]}'),
(323, 'e3_n3_s2', 'Kad Tarikh', 'Susun tarikh mengikut urutan.', '1', 'Menyusun 13 Mei 1969, 4 Mac 1970 dan 31 Ogos 1970.', '{"timelineItems": [{"id": 1, "year": "13 Mei 1969", "text": "Rusuhan kaum dan MAGERAN", "why": "Peristiwa pencetus."}, {"id": 2, "year": "4 Mac 1970", "text": "Jawatankuasa Rukun Negara di bawah MAPEN merangka", "why": "Perundingan 66 wakil."}, {"id": 3, "year": "31 Ogos 1970", "text": "Rukun Negara diisytiharkan", "why": "Pengisytiharan Diraja."}], "aftermath": "Kad tarikh bercampur dan urutan peristiwa kabur.", "turns": [{"after": 4, "options": [{"text": "Wakil dari pelbagai pihak supaya semua suara didengar.", "isCorrect": true, "reaction": "Sambanthan mengangguk."}, {"text": "Supaya satu parti memutuskan semuanya, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Sambanthan menggeleng. Itu tidak adil."}, {"text": "Supaya mesyuarat menjadi lebih besar sahaja.", "isCorrect": false, "reaction": "Pegawai keliru kerana jawapan itu tiada sebab."}], "clue": "Pelbagai wakil supaya semua didengar."}]}'),
(324, 'e3_n3_s3', 'Catatan Pengisytiharan', 'Nyahkod catatan dan pilih jawapan yang betul.', '5', 'Mengetahui siapa yang memasyhurkan Rukun Negara.', '{"clueText": "Catatan: Rukun Negara dimasyhurkan sebagai Pengisytiharan Diraja oleh ____ pada 31 Ogos 1970.", "options": [{"text": "Yang di-Pertuan Agong Keempat", "isCorrect": true}, {"text": "Yang di-Pertuan Agong Pertama", "isCorrect": false, "consequence": "Itu bukan baginda yang memasyhurkan. Catatan dikembalikan."}, {"text": "Perdana Menteri", "isCorrect": false, "consequence": "Perdana Menteri bukan yang memasyhurkan. Pegawai keliru."}, {"text": "Tun Abdul Razak", "isCorrect": false, "consequence": "Beliau pengarah MAGERAN, bukan yang memasyhurkan."}], "aftermath": "Catatan tersalah dibaca dan pengisytiharan tidak dicatat dengan betul.", "turns": [{"after": 4, "options": [{"text": "Murid perlu tahu supaya mereka menghayati Rukun Negara.", "isCorrect": true, "reaction": "Murid tersenyum."}, {"text": "Murid tidak perlu tahu kerana itu urusan orang dewasa.", "isCorrect": false, "reaction": "Pegawai membantah. Semua rakyat perlu tahu."}, {"text": "Murid tahu supaya boleh bermain sahaja dan lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Tujuannya ialah penghayatan."}], "clue": "Penghayatan bermula dengan pengetahuan."}]}'),
(325, 'e3_n3_s4', 'Cari Lima Matlamat', 'Cari lima papan matlamat.', '2', 'Mengenal lima matlamat Rukun Negara.', '{"bgImage": "../assets/gameAsset/background/matlamat_rukun_negara_dahulu.png", "hotspots": [{"name": "Papan perpaduan lebih erat", "top": "20%", "left": "20%"}, {"name": "Papan demokrasi", "top": "30%", "left": "50%"}, {"name": "Papan masyarakat adil", "top": "50%", "left": "30%"}, {"name": "Papan cara liberal terhadap kebudayaan", "top": "60%", "left": "70%"}, {"name": "Papan masyarakat progresif", "top": "75%", "left": "45%"}], "aftermath": "Papan tidak ditemui dan murid keliru tentang lima matlamat.", "turns": [{"after": 5, "options": [{"text": "Matlamat pertama ialah perpaduan yang lebih erat.", "isCorrect": true, "reaction": "Murid mengangguk dan tersenyum."}, {"text": "Menurut aku, matlamat pertama ialah sains dan teknologi.", "isCorrect": false, "reaction": "Itu matlamat kelima. Murid membetulkan."}, {"text": "Matlamat pertama ialah demokrasi, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Itu matlamat kedua. Murid menggeleng."}], "clue": "Matlamat pertama ialah perpaduan."}]}'),
(326, 'e3_n3_s5', 'Situasi dan Prinsip', 'Padankan situasi dengan prinsip.', '4', 'Menerapkan prinsip Rukun Negara dalam situasi.', '{"pairs": [{"text": "Berdoa mengikut kepercayaan masing-masing", "pair": 1}, {"text": "Kepercayaan kepada Tuhan", "pair": 1}, {"text": "Rela berkorban demi negara", "pair": 2}, {"text": "Kesetiaan kepada Raja dan Negara", "pair": 2}, {"text": "Menggubal undang-undang di Parlimen", "pair": 3}, {"text": "Keluhuran Perlembagaan", "pair": 3}, {"text": "Mematuhi undang-undang jalan raya", "pair": 4}, {"text": "Kedaulatan Undang-undang", "pair": 4}, {"text": "Memimpin nenek melintas jalan", "pair": 5}, {"text": "Kesopanan dan Kesusilaan", "pair": 5}], "aftermath": "Padanan tersilap dan murid keliru menerapkan prinsip.", "turns": [{"after": 5, "options": [{"text": "Kesopanan dan kesusilaan ialah nilai murni.", "isCorrect": true, "reaction": "Murid tersenyum dan mengangguk."}, {"text": "Rasanya, kesopanan dan kesusilaan ialah undang-undang tertinggi.", "isCorrect": false, "reaction": "Itu Keluhuran Perlembagaan. Murid membetulkan."}, {"text": "Kesopanan dan kesusilaan ialah taat setia kepada raja.", "isCorrect": false, "reaction": "Itu Kesetiaan kepada Raja dan Negara."}], "clue": "Kesopanan ialah nilai murni."}]}'),
(327, 'e3_n3_s6', 'Juadah Perayaan', 'Serahkan kad yang betul kepada murid.', '3', 'Memahami masyarakat beragama mengelakkan dengki, rasuah, dadah dan keruntuhan moral.', '{"npcName": "Murid Sekolah", "prompt": "Saya mahu tahu masyarakat beragama dapat mengelakkan apa. Kad yang mana?", "options": [{"text": "Dengki, khianat, rasuah, dadah dan keruntuhan moral", "item": "dokumen", "isCorrect": true}, {"text": "Hari perayaan, juadah dan jemputan", "item": "dokumen", "isCorrect": false, "consequence": "Itu bukan perkara yang dielakkan. Murid keliru."}, {"text": "Sains, teknologi dan pelajaran", "item": "dokumen", "isCorrect": false, "consequence": "Itu bukan perkara yang dielakkan. Murid menggeleng."}, {"text": "Bunga, bendera dan lagu", "item": "dokumen", "isCorrect": false, "consequence": "Itu bukan perkara yang dielakkan. Murid mengerutkan dahi."}], "aftermath": "Kad salah diserahkan dan murid tidak faham kepentingan agama.", "turns": [{"after": 5, "options": [{"text": "Bagi aku, menghormati agama orang lain mengukuhkan perpaduan.", "isCorrect": true, "reaction": "Pak Tani dan Tauke Lim mengangguk."}, {"text": "Bagi aku, menghormati agama orang lain melemahkan perpaduan.", "isCorrect": false, "reaction": "Tauke Lim menggeleng. Itu bertentangan."}, {"text": "Bagi aku, agama orang lain tidak penting, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pak Tani membantah. Semua agama dihormati."}], "clue": "Hormat agama mengukuhkan perpaduan."}]}'),
(328, 'e3_n3_s7', 'Bukti di Bandar', 'Cari tiga bukti peranan Rukun Negara.', '2', 'Memahami peranan menghormati undang-undang dan mengukuhkan perpaduan.', '{"bgImage": "../assets/gameAsset/background/bandar.png", "hotspots": [{"name": "Poster kempen patuh undang-undang", "top": "28%", "left": "22%"}, {"name": "Pasar pelbagai kaum", "top": "62%", "left": "58%"}, {"name": "Papan tanda trafik dipatuhi", "top": "40%", "left": "80%"}], "aftermath": "Bukti tidak lengkap dan belia tidak yakin dengan peranan Rukun Negara.", "turns": [{"after": 4, "options": [{"text": "Sebenarnya, mematuhi undang-undang mewujudkan keamanan dan kesejahteraan.", "isCorrect": true, "reaction": "Belia mengangguk."}, {"text": "Mematuhi undang-undang menambah jenayah, jadi tidak perlu dipedulikan lagi.", "isCorrect": false, "reaction": "Belia ketawa. Jawapan itu terbalik."}, {"text": "Mematuhi undang-undang tidak penting, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tauke Lim menggeleng. Ia penting untuk semua."}], "clue": "Patuh undang-undang membawa keamanan."}]}'),
(329, 'e3_n3_s8', 'Rumusan Enam Peranan', 'Padankan peranan dengan maksudnya.', '4', 'Merumus enam peranan Rukun Negara.', '{"pairs": [{"text": "Meraikan kepelbagaian agama", "pair": 1}, {"text": "Hormat amalan agama orang lain", "pair": 1}, {"text": "Masyarakat patriotik", "pair": 2}, {"text": "Hormat lambang kedaulatan negara", "pair": 2}, {"text": "Menghormati undang-undang", "pair": 3}, {"text": "Keamanan dan kesejahteraan", "pair": 3}, {"text": "Mengukuhkan perpaduan", "pair": 4}, {"text": "Permuafakatan dan toleransi", "pair": 4}, {"text": "Menerapkan nilai murni", "pair": 5}, {"text": "Hubungan harmoni", "pair": 5}, {"text": "Membentuk jati diri", "pair": 6}, {"text": "Rakyat yang berintegriti", "pair": 6}], "aftermath": "Padanan tersilap dan rumusan terbantut.", "turns": [{"after": 6, "options": [{"text": "Integriti ialah kejujuran yang tulen dan tidak berubah.", "isCorrect": true, "reaction": "Murid mengangguk dan menulis jawapan itu."}, {"text": "Integriti ialah menipu apabila tidak dilihat, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Murid terkejut. Itu bertentangan dengan kejujuran."}, {"text": "Rasanya, integriti hanya penting semasa peperiksaan.", "isCorrect": false, "reaction": "Guru menggeleng. Integriti perlu setiap masa."}], "clue": "Integriti ialah kejujuran yang tulen."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e3_n1_s1', 'hint', 'Rusuhan 13 Mei 1969 membawa kepada MAGERAN.', NULL, NULL),
(301, NULL, 'hint', 'Namanya bermula dengan Majlis Gerakan. Baca nota dan lihat papan tanda.', 'Selepas rusuhan kaum 13 Mei 1969, MAGERAN mengambil alih pentadbiran negara dan Tun Abdul Razak menjadi pengarahnya.', 'Tepat! MAGERAN dikenal pasti. Pegawai Kanan menyerahkan satu fail tebal, iaitu laporan tentang punca kaum berpecah.'),
(NULL, 'e3_n1_s2', 'hint', 'Tiga kegiatan, tiga kaum, tiga tempat.', NULL, NULL),
(302, NULL, 'hint', 'Cari sawah, lombong dan ladang di atas peta.', 'Punca pertama ialah perbezaan kegiatan ekonomi. Orang Melayu bertani sara diri, orang Cina melombong dan berniaga, orang India bekerja di ladang. Jurang ekonomi itu tidak seimbang.', 'Berjaya! Tiga bukti ditemui. Pak Muthu menunjuk ke arah deretan rumah ladang, ''Kami tinggal di sana, Tun, jauh dari orang lain.'''),
(NULL, 'e3_n1_s3', 'hint', 'Tempat tinggal berasingan, jarang berinteraksi.', NULL, NULL),
(303, NULL, 'hint', 'Tiga petempatan, iaitu kampung, bandar, ladang. Fikirkan sama ada mereka sering bertemu.', 'Punca kedua ialah tempat tinggal yang berasingan, iaitu kampung, bandar dan ladang, sehingga kaum kurang berinteraksi. Punca ketiga ialah perbezaan fahaman politik yang merenggangkan hubungan.', 'Tepat! Tauke Lim mengangguk. ''Kalau kita bertegur sapa lebih awal, mungkin lain ceritanya, Tun.'' Pegawai Kanan, ''Tun, jawatankuasa perlu dibentuk.'''),
(NULL, 'e3_n1_s4', 'hint', 'Tarikh 4 Mac 1970. Bilangan wakil, iaitu enam puluh enam.', NULL, NULL),
(304, NULL, 'hint', 'Cari tarikh 4 Mac 1970 dan nama badan yang dianggotai 66 wakil.', 'MAPEN ialah Majlis Perundingan Negara yang dianggotai 66 wakil. Jawatankuasa Rukun Negara di bawahnya merangka Rukun Negara pada 4 Mac 1970.', 'Betul! Surat dihantar dan jawatankuasa bersidang. Pegawai Kanan, iaitu XX'),
(NULL, 'e3_n1_s5', 'hint', 'Matlamat pertama ialah perpaduan yang lebih erat.', NULL, NULL),
(305, NULL, 'hint', 'Lima matlamat, lima maksud. Padankan mengikut susunan yang disebut.', 'Lima matlamat Rukun Negara ialah perpaduan yang lebih erat, cara hidup demokrasi, masyarakat adil, cara liberal terhadap kebudayaan yang kaya dan masyarakat progresif yang menggunakan sains dan teknologi moden.', 'Hebat! Semua matlamat dipadankan. Sambanthan menepuk tangan. Pegawai Kanan menghulur tarikh yang bakal ditulis dalam sejarah.'),
(NULL, 'e3_n1_s6', 'hint', 'Tiga tarikh, iaitu 13 Mei 1969, 4 Mac 1970, 31 Ogos 1970.', NULL, NULL),
(306, NULL, 'hint', 'Mulakan dengan rusuhan, kemudian MAPEN, kemudian pengisytiharan.', 'Tiga tarikh penting ialah 13 Mei 1969, 4 Mac 1970 dan 31 Ogos 1970. Rusuhan kaum mendorong Rukun Negara diisytiharkan sebagai Pengisytiharan Diraja.', 'Betul! Peristiwa tersusun. Yang di-Pertuan Agong Keempat membaca pengisytiharan di hadapan semua. Sambanthan berbisik, ''Tun, sekarang lima prinsip pula.'''),
(NULL, 'e3_n1_s7', 'hint', 'Dua prinsip pertama, iaitu Tuhan, kemudian raja dan negara.', NULL, NULL),
(307, NULL, 'hint', 'Prinsip pertama berkait dengan agama. Prinsip kedua berkait dengan Ketua Utama Negara.', 'Prinsip pertama ialah Kepercayaan kepada Tuhan, iaitu agama menjadi pegangan utama dan amalan beragama orang lain dihormati. Prinsip kedua ialah Kesetiaan kepada Raja dan Negara, kerana Yang di-Pertuan Agong ialah Ketua Utama Negara.', 'Tepat! Murid menyerahkan kad itu. Guru memuji. Pegawai MAGERAN datang dengan wajah ceria, ''Tun, tiga prinsip lagi menunggu.'''),
(NULL, 'e3_n1_s8', 'hint', 'Perlembagaan dan undang-undang, iaitu dua prinsip berkait rapat.', NULL, NULL),
(308, NULL, 'hint', 'Cari buku Perlembagaan, palu hakim dan papan notis undang-undang.', 'Prinsip ketiga ialah Keluhuran Perlembagaan, kerana Perlembagaan ialah undang-undang tertinggi. Prinsip keempat ialah Kedaulatan Undang-undang, iaitu setiap rakyat menghormati dan mematuhi undang-undang untuk menjamin keharmonian.', 'Berjaya! Tiga bukti ditemui. Arun mencatat kata-kata Tun. Pegawai Kanan, ''Tun, prinsip terakhir pula.'''),
(NULL, 'e3_n1_s9', 'hint', 'Memimpin nenek berkait dengan nilai murni.', NULL, NULL),
(309, NULL, 'hint', 'Lima situasi, lima prinsip. Baca situasi dan fikirkan prinsip mana yang paling sesuai.', 'Prinsip kelima ialah Kesopanan dan Kesusilaan, iaitu nilai murni, disiplin dan akhlak mulia. Kelima-lima prinsip dapat dilihat dalam situasi harian kita.', 'Hebat! Semua situasi dipadankan dengan prinsip yang betul. Murid bertepuk tangan dan Pegawai MAGERAN membuka pintu, ''Tun, rakyat sedang menunggu penerangan peranan Rukun Negara.'''),
(NULL, 'e3_n1_s10', 'hint', 'Peranan agama dan peranan patriotik.', NULL, NULL),
(310, NULL, 'hint', 'Baca perkataan agama dan lambang kedaulatan dalam nota.', 'Rukun Negara meraikan kepelbagaian agama dan membentuk masyarakat patriotik yang menghormati Jalur Gemilang, Jata Negara dan Negaraku. Masyarakat beragama juga dapat mengelakkan dengki, rasuah, dadah dan keruntuhan moral.', 'Tepat! Hafiz berkata, ''Sekarang saya faham mengapa kami berdiri bersama.'' Pegawai Kanan, ''Tun, dua peranan lagi.'''),
(NULL, 'e3_n1_s11', 'hint', 'Undang-undang dan perpaduan, iaitu dua peranan.', NULL, NULL),
(311, NULL, 'hint', 'Cari poster kempen, pasar pelbagai kaum dan papan tanda trafik.', 'Rukun Negara memupuk sikap menghormati undang-undang untuk keamanan dan kesejahteraan, dan mengukuhkan perpaduan melalui permuafakatan dan toleransi. Budaya kaum lain turut dihormati.', 'Berjaya! Tiga bukti ditemui. Wei Jie menghulur sehelai poster, ''Tun, anak muda mahu tahu peranan terakhir.'''),
(NULL, 'e3_n1_s12', 'hint', 'Nilai murni dan jati diri menutup enam peranan.', NULL, NULL),
(312, NULL, 'hint', 'Enam peranan, enam maksud. Ingat contoh yang disebut tentang integriti dan lambang kedaulatan.', 'Enam peranan Rukun Negara ialah meraikan kepelbagaian agama, membentuk masyarakat patriotik, menghormati undang-undang, mengukuhkan perpaduan, menerapkan nilai murni dan membentuk jati diri. Integriti ialah kejujuran yang tulen, contohnya tidak meniru dalam peperiksaan.', 'Tepat! Enam peranan dipadankan. Murid mengangkat tangan, ''Terima kasih, Pak Cik!'' Tugas bersejarah selesai, Rukun Negara hidup dalam hati rakyat.'),
(NULL, 'e3_n2_s1', 'hint', 'Tiga petempatan, kurang berinteraksi.', NULL, NULL),
(313, NULL, 'hint', 'Cari kampung, bandar dan ladang di atas peta.', 'Orang Melayu tinggal di kampung dan pedalaman, orang Cina di bandar, orang India di ladang. Akibatnya, mereka kurang peluang berinteraksi.', 'Betul! Tiga petempatan ditemui. Pak Tani menghulur tangan kepada Pak Muthu buat kali pertama.'),
(NULL, 'e3_n2_s2', 'hint', 'Fahaman politik ialah sebab ketiga.', NULL, NULL),
(314, NULL, 'hint', 'Dua sebab pertama sudah dinyatakan. Cari yang ketiga.', 'Tiga punca rusuhan ialah perbezaan kegiatan ekonomi, pengasingan tempat tinggal dan perbezaan fahaman politik. Ia berakhir dengan rusuhan kaum 13 Mei 1969.', 'Tepat! Arun menulis jawapan itu. Pegawai Kanan, ''Tun, Majlis Perundingan Negara akan bersidang.'''),
(NULL, 'e3_n2_s3', 'hint', 'Enam puluh enam wakil, 4 Mac 1970.', NULL, NULL),
(315, NULL, 'hint', 'Cari dokumen dengan nombor 66 dan tarikh 4 Mac 1970.', 'MAPEN mempunyai 66 wakil, dan Jawatankuasa Rukun Negara merangka Rukun Negara pada 4 Mac 1970.', 'Betul! Hafiz membacakan dokumen itu. Semua wakil menyepi, mendengar dengan teliti.'),
(NULL, 'e3_n2_s4', 'hint', 'Lima matlamat, lima contoh.', NULL, NULL),
(316, NULL, 'hint', 'Padankan lima matlamat dengan contoh yang disebut tadi.', 'Lima matlamat ialah perpaduan, demokrasi, masyarakat adil, cara liberal terhadap kebudayaan dan masyarakat progresif.', 'Hebat! Poster-poster tersusun. Sambanthan tersenyum kepada orang ramai.'),
(NULL, 'e3_n2_s5', 'hint', '31 Ogos 1970, YDPA Keempat.', NULL, NULL),
(317, NULL, 'hint', 'Cari tarikh 31 Ogos 1970 dan gelaran Keempat.', 'Rukun Negara diisytiharkan pada 31 Ogos 1970 oleh Yang di-Pertuan Agong Keempat sebagai Pengisytiharan Diraja.', 'Betul! Kad diserahkan. Baginda memulakan bacaan dengan lantang.'),
(NULL, 'e3_n2_s6', 'hint', 'Lima prinsip, lima maksud.', NULL, NULL),
(318, NULL, 'hint', 'Padankan lima prinsip mengikut susunannya.', 'Lima prinsip ialah Tuhan, raja dan negara, perlembagaan, undang-undang dan kesopanan. Yang di-Pertuan Agong ialah Ketua Utama Negara.', 'Hebat! Lima prinsip dipadankan. Murid bertepuk tangan.'),
(NULL, 'e3_n2_s7', 'hint', 'Agama dihormati, negara disayangi.', NULL, NULL),
(319, NULL, 'hint', 'Cari rumah ibadat, Jalur Gemilang dan penduduk berjalan bersama.', 'Rukun Negara meraikan kepelbagaian agama dan membentuk masyarakat patriotik.', 'Berjaya! Tiga bukti ditemui. Hafiz tersenyum melihat jirannya berlainan agama menyambut perayaan bersama.'),
(NULL, 'e3_n2_s8', 'hint', 'Undang-undang dan perpaduan.', NULL, NULL),
(320, NULL, 'hint', 'Permuafakatan dan toleransi memberi kesan kepada hubungan kaum.', 'Rukun Negara menggalakkan kita menghormati undang-undang untuk keamanan dan kesejahteraan, serta mengukuhkan perpaduan melalui permuafakatan dan toleransi.', 'Tepat! Wei Jie tersenyum. Tauke Lim menepuk bahunya.'),
(NULL, 'e3_n2_s9', 'hint', 'Enam peranan dirumus bersama.', NULL, NULL),
(321, NULL, 'hint', 'Enam peranan. Padankan semuanya.', 'Enam peranan Rukun Negara sudah dirumus. Integriti ialah kejujuran yang tulen dan tidak berubah.', 'Tepat! Murid-murid bertepuk tangan. Rukun Negara kini hidup di hati rakyat.'),
(NULL, 'e3_n3_s1', 'hint', 'Tiga sebab membawa kepada rusuhan.', NULL, NULL),
(322, NULL, 'hint', 'Tiga sebab, tiga perincian.', 'Tiga punca ialah kegiatan ekonomi, tempat tinggal dan fahaman politik. Rusuhan 13 Mei 1969 membawa kepada MAGERAN.', 'Betul! Sebab dan perincian dipadankan. Tunku menarik nafas panjang.'),
(NULL, 'e3_n3_s2', 'hint', 'Tarikh disusun dengan betul.', NULL, NULL),
(323, NULL, 'hint', 'Mulakan dengan rusuhan, kemudian perundingan, kemudian pengisytiharan.', 'Tiga tarikh itu ialah 13 Mei 1969, 4 Mac 1970 dan 31 Ogos 1970. MAPEN mempunyai 66 wakil.', 'Betul! Tarikh tersusun. Sambanthan tersenyum.'),
(NULL, 'e3_n3_s3', 'hint', 'YDPA Keempat memasyhurkan Rukun Negara.', NULL, NULL),
(324, NULL, 'hint', 'Cari gelaran yang menyebut nombor ke-4.', 'Pengisytiharan pada 31 Ogos 1970 dilakukan oleh Yang di-Pertuan Agong Keempat, Tuanku Sultan Ismail Nasiruddin Shah.', 'Tepat! Catatan dibetulkan. Orang ramai bertepuk tangan.'),
(NULL, 'e3_n3_s4', 'hint', 'Lima matlamat ditemui.', NULL, NULL),
(325, NULL, 'hint', 'Lima papan matlamat tersebar di dewan.', 'Lima matlamat itu ialah perpaduan, demokrasi, masyarakat adil, cara liberal terhadap kebudayaan, masyarakat progresif.', 'Berjaya! Lima papan ditemui. Murid menyebutnya dengan lantang.'),
(NULL, 'e3_n3_s5', 'hint', 'Lima prinsip, lima situasi.', NULL, NULL),
(326, NULL, 'hint', 'Lima situasi, lima prinsip.', 'Lima prinsip kini dapat dipadankan dengan situasi harian.', 'Hebat! Semua situasi dipadankan. Tiang-tiang menjadi lambang bangsa.'),
(NULL, 'e3_n3_s6', 'hint', 'Agama mengelakkan dengki dan rasuah.', NULL, NULL),
(327, NULL, 'hint', 'Cari kad yang menyenaraikan keburukan akhlak.', 'Masyarakat beragama dapat mengelakkan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.', 'Betul! Murid menulis semuanya di buku catatannya.'),
(NULL, 'e3_n3_s7', 'hint', 'Undang-undang dan perpaduan ada di sekeliling.', NULL, NULL),
(328, NULL, 'hint', 'Cari poster, pasar dan papan tanda.', 'Menghormati undang-undang membawa keamanan dan kesejahteraan, manakala permuafakatan dan toleransi mengukuhkan perpaduan.', 'Berjaya! Tiga bukti ditemui. Belia bersorak.'),
(NULL, 'e3_n3_s8', 'hint', 'Satu ikrar untuk semua rakyat.', NULL, NULL),
(329, NULL, 'hint', 'Enam peranan. Padankan semuanya.', 'Enam peranan Rukun Negara ialah agama, patriotik, undang-undang, perpaduan, nilai murni dan jati diri.', 'Tepat! Murid dan guru bertepuk tangan. Tunku mengangkat tangan, ''Satu Malaysia, satu ikrar.''');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(5, 301, NULL, 'Tugasku ialah menenangkan negara selepas 13 Mei 1969, mendengar semua pihak dan merangka satu ideologi yang menyatukan rakyat. Satu kesilapan boleh mencetuskan perpecahan baharu, {nama}.', 1),
(5, 301, NULL, 'Aku belajar bahawa perpaduan tidak lahir daripada paksaan, tetapi daripada pegangan bersama yang dihayati oleh semua kaum.', 2),
(5, 301, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin yang mentadbir negara melalui MAGERAN selepas peristiwa 13 Mei 1969. Keputusanmu menentukan masa depan perpaduan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(43, 301, 'e3_n1_s1', 'Tun, jalan sudah sunyi tetapi rakyat masih curiga antara satu sama lain. Siapa yang kini mentadbir negara?', 1),
(NULL, 301, 'e3_n1_s1', 'Selepas rusuhan kaum 13 Mei 1969, sebuah majlis khas mengambil alih. Namanya Majlis Gerakan Negara, ringkasnya MAGERAN.', 2),
(42, 301, 'e3_n1_s1', 'Nota ini menyebut majlis itu dibentuk selepas rusuhan, bukan sebelumnya. Tetapi tulisannya tergesa-gesa.', 3),
(NULL, 301, 'e3_n1_s1', 'Betul. Kita tenangkan negara dahulu, kemudian cari punca supaya ia tidak berulang.', 4),
(43, 301, 'e3_n1_s1', 'Tun, jika orang bertanya mengapa pentadbiran biasa tidak diteruskan, apa jawapan kita?', 5),
(43, 301, 'e3_n1_s2', 'Tun, pentadbiran British membawa masuk pekerja dari luar untuk sektor ekonomi. Setiap kaum diberi kerja yang berbeza.', 1),
(NULL, 301, 'e3_n1_s2', 'Orang Melayu bertani sara diri. Orang Cina melombong dan berniaga. Orang India bekerja di ladang.', 2),
(42, 301, 'e3_n1_s2', 'Maka jurang ekonomi tidak seimbang, Tun. Itulah sebab pertama laporan ini.', 3),
(45, 301, 'e3_n1_s2', 'Tun, saya Pak Tani. Kami menanam padi untuk makan sendiri. Kami tidak bertemu pelombong atau peniaga.', 4),
(46, 301, 'e3_n1_s2', 'Saya Pak Muthu, penoreh getah. Kami bekerja di ladang sejak pagi, jauh daripada kampung dan pekan.', 5),
(43, 301, 'e3_n1_s2', 'Tun, tiga kegiatan itu ada bukti di peta. Cari semuanya, kerana wakil rakyat mahu melihat sendiri.', 6),
(42, 301, 'e3_n1_s3', 'Tun, orang Melayu tinggal di kampung dan pedalaman. Orang Cina di bandar. Orang India di kawasan ladang.', 1),
(NULL, 301, 'e3_n1_s3', 'Mereka hidup berasingan sehingga jarang bertemu. Apa akibatnya, kalau orang tidak pernah berbual?', 2),
(44, 301, 'e3_n1_s3', 'Saya Tauke Lim, peniaga rumah kedai. Saya jarang bertemu jiran Melayu atau India. Kami bertegur sapa hanya di pasar.', 3),
(43, 301, 'e3_n1_s3', 'Tun, ada satu lagi sebab dalam laporan. Perbezaan fahaman politik merenggangkan hubungan kaum.', 4),
(42, 301, 'e3_n1_s3', 'Keadaan itu tidak harmoni, Tun, sehingga mencetuskan rusuhan kaum 13 Mei 1969.', 5),
(44, 301, 'e3_n1_s3', 'Seingat saya, jawapannya ialah kurang peluang berinteraksi antara masyarakat.', 6),
(43, 301, 'e3_n1_s3', 'Tun, nota ini tidak lengkap. Apakah akibat langsung daripada tempat tinggal yang berasingan?', 7),
(43, 301, 'e3_n1_s4', 'Tun, Majlis Perundingan Negara, ringkasnya MAPEN, akan bersidang. Ia dianggotai 66 orang wakil dari pelbagai pihak.', 1),
(NULL, 301, 'e3_n1_s4', 'Wakil daripada MAGERAN, kerajaan negeri, parti politik, Sarawak dan Sabah, kumpulan agama, badan profesional dan lain-lain.', 2),
(41, 301, 'e3_n1_s4', 'Saya Sambanthan. Saya mewakili suara rakyat berbilang kaum. Rukun Negara mesti lahir daripada perundingan bersama.', 3),
(43, 301, 'e3_n1_s4', 'Pada 4 Mac 1970, Jawatankuasa Rukun Negara di bawah MAPEN merangka dan memperkenalkan Rukun Negara.', 4),
(42, 301, 'e3_n1_s4', 'Tun, saya perlu menghantar surat jemputan kepada jawatankuasa. Surat yang manakah yang betul?', 5),
(41, 301, 'e3_n1_s5', 'Tun, Rukun Negara mempunyai lima matlamat. Pertama, mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat.', 1),
(NULL, 301, 'e3_n1_s5', 'Kedua, memelihara satu cara hidup demokrasi. Ketiga, mencipta masyarakat yang adil supaya kemakmuran dinikmati secara adil dan saksama.', 2),
(43, 301, 'e3_n1_s5', 'Keempat, menjamin cara yang liberal terhadap tradisi kebudayaan yang kaya dan pelbagai corak.', 3),
(42, 301, 'e3_n1_s5', 'Kelima, membina masyarakat progresif yang menggunakan sains dan teknologi moden.', 4),
(41, 301, 'e3_n1_s5', 'Tun, bantu wakil memadankan setiap matlamat dengan maksudnya sebelum persidangan bermula.', 5),
(43, 301, 'e3_n1_s6', 'Tun, Rukun Negara dimasyhurkan sebagai Pengisytiharan Diraja oleh Yang di-Pertuan Agong Keempat, Tuanku Sultan Ismail Nasiruddin Shah.', 1),
(NULL, 301, 'e3_n1_s6', 'Ia diisytiharkan bersempena ulang tahun Hari Kebangsaan yang ke-13, iaitu 31 Ogos 1970.', 2),
(42, 301, 'e3_n1_s6', 'Sebelum itu, MAPEN bersidang pada 4 Mac 1970 dan semuanya bermula dengan rusuhan 13 Mei 1969.', 3),
(52, 301, 'e3_n1_s6', 'Pak Cik, mengapa Rukun Negara diisytiharkan bersempena Hari Kebangsaan?', 4),
(43, 301, 'e3_n1_s6', 'Tun, kad peristiwa ini bercampur. Susun mengikut tarikh sebelum tetamu bertanya.', 5),
(52, 301, 'e3_n1_s7', 'Pak Cik, rumah ibadat berlainan agama ada di sini. Mengapa mereka boleh hidup aman?', 1),
(NULL, 301, 'e3_n1_s7', 'Prinsip pertama ialah Kepercayaan kepada Tuhan. Agama menjadi pegangan utama dan kita menghormati amalan beragama orang lain.', 2),
(43, 301, 'e3_n1_s7', 'Prinsip kedua pula Kesetiaan kepada Raja dan Negara. Setiap warganegara taat setia kepada Yang di-Pertuan Agong sebagai Ketua Utama Negara.', 3),
(42, 301, 'e3_n1_s7', 'Kedua-dua prinsip menyatupadukan rakyat berbilang kaum dan melahirkan semangat patriotik.', 4),
(52, 301, 'e3_n1_s7', 'Pak Cik, saya ada dua kad. Yang mana serahkan kepada guru untuk prinsip pertama?', 5),
(49, 301, 'e3_n1_s8', 'Tun, saya Arun. Saya diberitahu Perlembagaan Persekutuan ialah undang-undang tertinggi negara. Benarkah?', 1),
(NULL, 301, 'e3_n1_s8', 'Itulah Keluhuran Perlembagaan. Tiada institusi dapat mengatasi Perlembagaan, dan rakyat perlu menerima, mematuhi serta mempertahankannya.', 2),
(43, 301, 'e3_n1_s8', 'Prinsip keempat ialah Kedaulatan Undang-undang. Setiap rakyat perlu menghormati dan mematuhi undang-undang yang ditetapkan.', 3),
(42, 301, 'e3_n1_s8', 'Kepatuhan kepada undang-undang menjamin keharmonian masyarakat dan keselamatan negara.', 4),
(49, 301, 'e3_n1_s8', 'Tun, ada tiga bukti di bilik ini tentang dua prinsip itu. Boleh Tun cari bersama?', 5),
(52, 301, 'e3_n1_s9', 'Pak Cik, prinsip kelima ialah Kesopanan dan Kesusilaan. Apa maksudnya?', 1),
(NULL, 301, 'e3_n1_s9', 'Amalan nilai murni yang melambangkan keperibadian rakyat Malaysia. Ia membentuk masyarakat berdisiplin dan berakhlak mulia.', 2),
(43, 301, 'e3_n1_s9', 'Contoh situasi, iaitu seorang murid mematuhi undang-undang jalan raya. Seorang lagi memimpin nenek melintas jalan.', 3),
(42, 301, 'e3_n1_s9', 'Seorang graduan undang-undang menggubal undang-undang di Parlimen. Sebuah keluarga berdoa mengikut kepercayaan masing-masing.', 4),
(43, 301, 'e3_n1_s9', 'Seorang anggota komando rela berkorban demi kedaulatan negara. Tun, padankan situasi ini dengan prinsip yang betul.', 5),
(50, 301, 'e3_n1_s10', 'Tun, saya Hafiz. Jiran saya berlainan agama. Mengapa kami boleh berdiri bersama di sini?', 1),
(NULL, 301, 'e3_n1_s10', 'Rukun Negara berperanan mewujudkan rakyat yang bersatu padu dan bertoleransi. Prinsip kepercayaan kepada Tuhan membentuk rakyat yang patuh ajaran agama masing-masing.', 2),
(43, 301, 'e3_n1_s10', 'Masyarakat yang beragama dapat mengelakkan perasaan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.', 3),
(42, 301, 'e3_n1_s10', 'Rukun Negara juga membentuk masyarakat patriotik yang menghormati bendera Jalur Gemilang, Jata Negara dan lagu Negaraku.', 4),
(50, 301, 'e3_n1_s10', 'Tun, tolong nyahkod nota ini tentang peranan Rukun Negara.', 5),
(47, 301, 'e3_n1_s11', 'Tun, saya Wei Jie, sukarelawan kempen. Rukun Negara bimbing kami daripada terlibat dengan jenayah, betulkah?', 1),
(NULL, 301, 'e3_n1_s11', 'Ya. Rukun Negara memupuk sikap menghormati undang-undang. Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan.', 2),
(44, 301, 'e3_n1_s11', 'Saya Tauke Lim. Dahulu kami jarang bertemu jiran berlainan kaum. Kini kami belajar budaya masing-masing.', 3),
(43, 301, 'e3_n1_s11', 'Rukun Negara mengukuhkan perpaduan melalui permuafakatan dan toleransi.', 4),
(47, 301, 'e3_n1_s11', 'Tun, ada tiga bukti peranan itu di bandar ini. Boleh Tun carikan bersama?', 5),
(52, 301, 'e3_n1_s12', 'Pak Cik, saya masih keliru dengan dua peranan terakhir, nilai murni dan jati diri.', 1),
(NULL, 301, 'e3_n1_s12', 'Rukun Negara menerapkan nilai murni supaya hubungan harmoni dan saling menghormati. Ia juga membentuk jati diri masyarakat Malaysia yang berintegriti.', 2),
(43, 301, 'e3_n1_s12', 'Integriti bermaksud mempunyai sikap kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 3),
(42, 301, 'e3_n1_s12', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan.', 4),
(43, 301, 'e3_n1_s12', 'Seingat saya, Meraikan kepelbagaian agama dan kepercayaan berpasangan dengan Menghormati amalan agama orang lain, Masyarakat patriotik berpasangan dengan Menghormati bendera, Jata Negara dan lagu Negaraku.', 5),
(43, 301, 'e3_n1_s12', 'Dan seingat saya juga, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan terjamin, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 6),
(52, 301, 'e3_n1_s12', 'Pak Cik, boleh tolong padankan enam peranan dengan maksudnya supaya saya faham?', 7),
(41, 302, NULL, 'Aku mendengar suara rakyat dari satu pintu ke satu pintu. Perpaduan bermula apabila kita sudi bertegur sapa, {nama}.', 1),
(41, 302, NULL, 'Rakyat hanya menerima Rukun Negara jika mereka faham dan merasainya dalam hidup harian.', 2),
(41, 302, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil rakyat yang membawa suara pelbagai kaum ke meja perundingan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(42, 302, 'e3_n2_s1', 'Tun, rakyat berkata mereka hidup berasingan, Melayu di kampung, Cina di bandar dan India di ladang.', 1),
(NULL, 302, 'e3_n2_s1', 'Pengasingan tempat tinggal menyebabkan kurang peluang berinteraksi. Itu sebab kedua mengapa Rukun Negara diperlukan.', 2),
(45, 302, 'e3_n2_s1', 'Saya Pak Tani. Rumah saya di kampung dan saya jarang ke bandar. Saya tidak kenal orang ladang.', 3),
(46, 302, 'e3_n2_s1', 'Saya Pak Muthu. Kami tinggal di ladang, jauh dari kampung dan bandar, Tun.', 4),
(44, 302, 'e3_n2_s1', 'Saya Tauke Lim. Rumah kedai kami di bandar. Kami jarang bertemu jiran Melayu. Tun, tolong cari tiga petempatan ini di peta.', 5),
(42, 302, 'e3_n2_s2', 'Tun, laporan ini menyebut tiga sebab rusuhan. Dua sudah kita tahu, iaitu kegiatan ekonomi dan tempat tinggal.', 1),
(NULL, 302, 'e3_n2_s2', 'Sebab ketiga ialah perbezaan fahaman politik yang merenggangkan hubungan kaum, lalu mencetuskan rusuhan kaum 13 Mei 1969.', 2),
(43, 302, 'e3_n2_s2', 'Selepas rusuhan, MAGERAN mentadbir negara. Tun, laporan ini menyebut sebab ketiga tetapi ayat itu terpadam sebahagian.', 3),
(49, 302, 'e3_n2_s2', 'Tun, saya Arun. Boleh Tun bantu nyahkod ayat terpadam itu?', 4),
(43, 302, 'e3_n2_s3', 'Tun, MAPEN mempunyai 66 wakil dari pelbagai bidang. Mereka bersidang supaya semua suara didengar.', 1),
(NULL, 302, 'e3_n2_s3', 'Jawatankuasa Rukun Negara di bawah MAPEN ditubuhkan untuk merangka dan memperkenalkan Rukun Negara.', 2),
(42, 302, 'e3_n2_s3', 'Tarikhnya ialah 4 Mac 1970. Tun, setiausaha memerlukan dokumen yang betul untuk dibaca.', 3),
(50, 302, 'e3_n2_s3', 'Tun, saya Hafiz. Saya setiausaha. Dokumen yang manakah perlu saya bacakan?', 4),
(NULL, 302, 'e3_n2_s4', 'Rukun Negara ada lima matlamat, iaitu perpaduan lebih erat, demokrasi, masyarakat adil, cara liberal terhadap kebudayaan dan masyarakat progresif.', 1),
(NULL, 302, 'e3_n2_s4', 'Perpaduan lebih erat dalam kalangan seluruh masyarakat. Masyarakat adil bermakna kemakmuran dinikmati secara adil dan saksama.', 2),
(47, 302, 'e3_n2_s4', 'Saya Wei Jie. Cara liberal terhadap kebudayaan bermakna kita menghormati tradisi yang kaya dan pelbagai corak, bukan?', 3),
(52, 302, 'e3_n2_s4', 'Masyarakat progresif pula menggunakan sains dan teknologi moden, Pak Cik?', 4),
(47, 302, 'e3_n2_s4', 'Seingat saya, Cara hidup demokrasi berpasangan dengan Rakyat mengundi memilih wakil.', 5),
(NULL, 302, 'e3_n2_s4', 'Betul. Tolong padankan matlamat dan contohnya supaya semua orang faham.', 6),
(43, 302, 'e3_n2_s5', 'Tun, Rukun Negara diisytiharkan sebagai Pengisytiharan Diraja pada 31 Ogos 1970, bersempena ulang tahun Hari Kebangsaan ke-13.', 1),
(NULL, 302, 'e3_n2_s5', 'Baginda ialah Yang di-Pertuan Agong Keempat, Tuanku Sultan Ismail Nasiruddin Shah.', 2),
(52, 302, 'e3_n2_s5', 'Pak Cik, mengapa pengisytiharan itu bersempena Hari Kebangsaan?', 3),
(42, 302, 'e3_n2_s5', 'Tun, wakil rakyat mahu menyerahkan kad pengisytiharan kepada baginda. Kad yang mana?', 4),
(43, 302, 'e3_n2_s6', 'Prinsip pertama Kepercayaan kepada Tuhan. Kedua, Kesetiaan kepada Raja dan Negara. Ketiga, Keluhuran Perlembagaan.', 1),
(NULL, 302, 'e3_n2_s6', 'Keempat, Kedaulatan Undang-undang. Kelima, Kesopanan dan Kesusilaan.', 2),
(52, 302, 'e3_n2_s6', 'Pak Cik, Kesetiaan kepada Raja dan Negara bermaksud taat setia kepada Yang di-Pertuan Agong, bukan?', 3),
(43, 302, 'e3_n2_s6', 'Seingat saya, Kepercayaan kepada Tuhan berpasangan dengan Agama pegangan utama dan hormat amalan beragama, Kesopanan dan Kesusilaan berpasangan dengan Amalan nilai murni keperibadian rakyat.', 4),
(42, 302, 'e3_n2_s6', 'Betul. Yang di-Pertuan Agong ialah Ketua Utama Negara. Tun, tolong padankan prinsip dengan maksudnya.', 5),
(NULL, 302, 'e3_n2_s7', 'Rukun Negara meraikan kepelbagaian agama. Prinsip kepercayaan kepada Tuhan membentuk rakyat yang patuh ajaran agama masing-masing.', 1),
(43, 302, 'e3_n2_s7', 'Masyarakat beragama dapat mengelakkan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.', 2),
(42, 302, 'e3_n2_s7', 'Rukun Negara juga membentuk masyarakat patriotik yang menghormati Jalur Gemilang, Jata Negara dan Negaraku.', 3),
(50, 302, 'e3_n2_s7', 'Tun, bantu saya cari tiga bukti peranan ini di kawasan ini.', 4),
(47, 302, 'e3_n2_s8', 'Tun, saya Wei Jie. Rukun Negara membimbing kami menghormati undang-undang dan menguatkan perpaduan.', 1),
(NULL, 302, 'e3_n2_s8', 'Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan. Permuafakatan dan toleransi pula mengukuhkan perpaduan.', 2),
(44, 302, 'e3_n2_s8', 'Saya Tauke Lim. Kami dan jiran kini belajar budaya masing-masing. Jarak antara kami sudah berkurang.', 3),
(47, 302, 'e3_n2_s8', 'Tun, boleh Tun nyahkod nota ini tentang peranan Rukun Negara di bandar?', 4),
(52, 302, 'e3_n2_s9', 'Pak Cik, apakah maksud integriti dalam jati diri masyarakat Malaysia?', 1),
(NULL, 302, 'e3_n2_s9', 'Integriti ialah sikap kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 2),
(43, 302, 'e3_n2_s9', 'Rukun Negara menerapkan nilai murni supaya hubungan harmoni dan saling menghormati. Ia juga membentuk jati diri yang berintegriti.', 3),
(52, 302, 'e3_n2_s9', 'Seingat saya, Meraikan kepelbagaian agama berpasangan dengan Hormat amalan agama orang lain, Masyarakat patriotik berpasangan dengan Hormat Jalur Gemilang, Jata Negara dan Negaraku.', 4),
(52, 302, 'e3_n2_s9', 'Dan seingat saya juga, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 5),
(42, 302, 'e3_n2_s9', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan. Tun, murid mahu merumuskan enam peranan.', 6),
(1, 303, NULL, 'Aku telah menyaksikan kemerdekaan dan rusuhan. Aku mahu Rukun Negara menjadi ikrar yang dipegang semua rakyat, {nama}.', 1),
(1, 303, NULL, 'Rukun Negara akan hidup jika rakyat memegangnya dalam kehidupan harian.', 2),
(1, 303, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Bapa Kemerdekaan yang menyaksikan Rukun Negara diisytiharkan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(43, 303, 'e3_n3_s1', 'Tunku, laporan menyatakan rusuhan 13 Mei 1969 berpunca daripada tiga sebab yang berkait dengan jurang antara kaum.', 1),
(NULL, 303, 'e3_n3_s1', 'Pertama, perbezaan kegiatan ekonomi. Kedua, pengasingan tempat tinggal. Ketiga, perbezaan fahaman politik.', 2),
(42, 303, 'e3_n3_s1', 'Selepas rusuhan, MAGERAN mentadbir negara di bawah pengarah Tun Abdul Razak.', 3),
(43, 303, 'e3_n3_s1', 'Seingat saya, Perbezaan kegiatan ekonomi berpasangan dengan Melayu bertani, Cina berniaga, India di ladang.', 4),
(43, 303, 'e3_n3_s1', 'Tunku, nota ini mencampurkan sebab dan akibat. Tolong asingkan mengikut yang betul.', 5),
(41, 303, 'e3_n3_s2', 'Tunku, Majlis Perundingan Negara dianggotai 66 wakil. Jawatankuasa Rukun Negara di bawahnya bersidang pada 4 Mac 1970.', 1),
(NULL, 303, 'e3_n3_s2', 'Pada 13 Mei 1969, rusuhan berlaku. Pada 4 Mac 1970, jawatankuasa merangka. Rukun Negara kemudian diisytiharkan.', 2),
(42, 303, 'e3_n3_s2', 'Tunku, kad tarikh ini bercampur. Tolong susun mengikut tarikh.', 3),
(43, 303, 'e3_n3_s2', 'Tarikh kemuncak ialah 31 Ogos 1970, bersempena ulang tahun Hari Kebangsaan ke-13.', 4),
(43, 303, 'e3_n3_s3', 'Tunku, Yang di-Pertuan Agong Keempat ialah Tuanku Sultan Ismail Nasiruddin Shah. Baginda memasyhurkan Rukun Negara.', 1),
(NULL, 303, 'e3_n3_s3', 'Pengisytiharan Diraja itu menandakan Rukun Negara diterima oleh semua rakyat dan semua kaum.', 2),
(52, 303, 'e3_n3_s3', 'Tunku, mengapa pengisytiharan itu penting kepada murid?', 3),
(42, 303, 'e3_n3_s3', 'Tunku, tolong nyahkod catatan ini tentang pengisytiharan.', 4),
(NULL, 303, 'e3_n3_s4', 'Matlamat pertama, iaitu mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat. Kedua, iaitu memelihara satu cara hidup demokrasi.', 1),
(43, 303, 'e3_n3_s4', 'Ketiga, iaitu mencipta masyarakat adil supaya kemakmuran dinikmati secara adil dan saksama.', 2),
(42, 303, 'e3_n3_s4', 'Keempat, iaitu menjamin cara liberal terhadap tradisi kebudayaan yang kaya dan pelbagai corak.', 3),
(52, 303, 'e3_n3_s4', 'Kelima, iaitu membina masyarakat progresif yang menggunakan sains dan teknologi moden.', 4),
(NULL, 303, 'e3_n3_s4', 'Tolong cari lima matlamat ini di dalam dewan supaya semua orang melihat sendiri.', 5),
(NULL, 303, 'e3_n3_s5', 'Lima prinsip menyokong bangsa. Kepercayaan kepada Tuhan, Kesetiaan kepada Raja dan Negara, Keluhuran Perlembagaan, Kedaulatan Undang-undang, Kesopanan dan Kesusilaan.', 1),
(43, 303, 'e3_n3_s5', 'Keluhuran Perlembagaan bermaksud Perlembagaan ialah undang-undang tertinggi. Kedaulatan Undang-undang bermaksud rakyat menghormati dan mematuhi undang-undang.', 2),
(52, 303, 'e3_n3_s5', 'Tunku, Kesopanan dan Kesusilaan ialah nilai murni, bukan?', 3),
(43, 303, 'e3_n3_s5', 'Seingat saya, Memimpin nenek melintas jalan berpasangan dengan Kesopanan dan Kesusilaan.', 4),
(42, 303, 'e3_n3_s5', 'Betul. Tunku, tolong padankan situasi dengan prinsip.', 5),
(45, 303, 'e3_n3_s6', 'Tunku, dahulu kami tidak bertegur sapa. Kini kami berkongsi juadah pada hari perayaan.', 1),
(44, 303, 'e3_n3_s6', 'Rukun Negara mengajar kami meraikan kepelbagaian agama dan saling menghormati.', 2),
(NULL, 303, 'e3_n3_s6', 'Itulah peranan Rukun Negara, iaitu meraikan kepelbagaian agama dan kepercayaan, serta membentuk masyarakat patriotik.', 3),
(45, 303, 'e3_n3_s6', 'Seingat saya, jawapannya ialah Dengki, khianat, rasuah, dadah dan keruntuhan moral.', 4),
(43, 303, 'e3_n3_s6', 'Tunku, murid mahu tahu apa yang boleh diperoleh daripada masyarakat yang beragama. Tolong beri juadah yang betul.', 5),
(47, 303, 'e3_n3_s7', 'Tunku, kami belia kempen. Kami diajar menghormati undang-undang dan bekerjasama dengan semua kaum.', 1),
(NULL, 303, 'e3_n3_s7', 'Itu dua peranan Rukun Negara, iaitu menghormati undang-undang dan mengukuhkan perpaduan.', 2),
(44, 303, 'e3_n3_s7', 'Saya Tauke Lim. Kami berniaga bersama jiran Melayu dan India. Perniagaan makin maju.', 3),
(47, 303, 'e3_n3_s7', 'Tunku, boleh Tunku carikan tiga bukti peranan ini di sekeliling kami?', 4),
(52, 303, 'e3_n3_s8', 'Tunku, apakah maksud jati diri yang berintegriti?', 1),
(NULL, 303, 'e3_n3_s8', 'Integriti ialah kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 2),
(43, 303, 'e3_n3_s8', 'Rukun Negara menerapkan nilai murni supaya hubungan harmoni dan saling menghormati.', 3),
(52, 303, 'e3_n3_s8', 'Seingat saya, Meraikan kepelbagaian agama berpasangan dengan Hormat amalan agama orang lain, Masyarakat patriotik berpasangan dengan Hormat lambang kedaulatan negara, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan.', 4),
(52, 303, 'e3_n3_s8', 'Dan seingat saya juga, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 5),
(42, 303, 'e3_n3_s8', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan. Tunku, tolong padankan enam peranan.', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (3, 3)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(301, 3, 'Bilakah Rukun Negara diisytiharkan?', '31 Ogos 1957', '16 September 1963', '31 Ogos 1970', '13 Mei 1969', 'C', 'Bersempena ulang tahun Hari Kebangsaan yang ke-13.', 'Rukun Negara diisytiharkan pada 31 Ogos 1970.'),
(302, 3, 'Siapakah yang memasyhurkan Rukun Negara sebagai Pengisytiharan Diraja?', 'Perdana Menteri', 'Yang di-Pertuan Agong Keempat', 'Yang di-Pertuan Agong Pertama', 'Tunku Abdul Rahman', 'B', 'Beliau Tuanku Sultan Ismail Nasiruddin Shah.', 'Rukun Negara dimasyhurkan oleh Yang di-Pertuan Agong Keempat.'),
(303, 3, 'Apakah nama badan yang mengambil alih pentadbiran negara selepas peristiwa 13 Mei 1969?', 'MAGERAN', 'MAPEN', 'JSKM', 'JAK', 'A', 'Majlis Gerakan Negara.', 'MAGERAN mentadbir negara selepas peristiwa 13 Mei 1969.'),
(304, 3, 'Apakah jawatankuasa yang merangka dan memperkenalkan Rukun Negara?', 'Jawatankuasa Antara Kerajaan', 'Jawatankuasa Setia Kawan Malaysia', 'Suruhanjaya Cobbold', 'Jawatankuasa Rukun Negara di bawah MAPEN', 'D', 'Ia di bawah Majlis Perundingan Negara.', 'Jawatankuasa Rukun Negara di bawah MAPEN merangkanya pada 4 Mac 1970.'),
(305, 3, 'Berapakah jumlah wakil dalam MAPEN?', '33 orang', '99 orang', '66 orang', '13 orang', 'C', 'Nombor enam enam.', 'MAPEN dianggotai 66 orang wakil daripada pelbagai pihak.'),
(306, 3, 'Manakah tiga sebab pengenalan Rukun Negara?', 'Kekurangan hasil padi, banjir dan kemarau', 'Perbezaan kegiatan ekonomi, pengasingan tempat tinggal, perbezaan fahaman politik', 'Perang dengan negara jiran, penyakit dan kemiskinan', 'Kekurangan sekolah, jalan raya dan elektrik', 'B', 'Tiga sebab berkait dengan kaum.', 'Tiga sebab ialah perbezaan kegiatan ekonomi, pengasingan tempat tinggal dan perbezaan fahaman politik.'),
(307, 3, 'Apakah kegiatan ekonomi utama orang Melayu pada zaman British?', 'Pertanian sara diri', 'Perlombongan dan perniagaan', 'Perladangan', 'Perkapalan', 'A', 'Mereka tinggal di kampung.', 'Orang Melayu menjalankan pertanian sara diri.'),
(308, 3, 'Apakah kegiatan ekonomi utama orang Cina pada zaman British?', 'Pertanian sara diri', 'Perladangan', 'Perikanan', 'Perlombongan dan perniagaan', 'D', 'Mereka tinggal di bandar.', 'Orang Cina menjalankan perlombongan dan perniagaan.'),
(309, 3, 'Orang India pada zaman British banyak bekerja dalam bidang...', 'perlombongan', 'perniagaan di bandar', 'perladangan', 'pertanian sara diri', 'C', 'Mereka tinggal di ladang.', 'Orang India banyak bekerja dalam perladangan.'),
(310, 3, 'Mengapakah pengasingan tempat tinggal menjadi sebab pengenalan Rukun Negara?', 'Perpaduan yang kukuh antara kaum', 'Kurangnya peluang berinteraksi antara masyarakat', 'Keharmonian semua kaum', 'Permuafakatan antara kaum', 'B', 'Mereka jarang berjumpa.', 'Pengasingan tempat tinggal menyebabkan kurangnya peluang berinteraksi.'),
(311, 3, 'Peristiwa rusuhan kaum yang membawa kepada Rukun Negara berlaku pada...', '13 Mei 1969', '31 Ogos 1957', '16 September 1963', '4 Mac 1970', 'A', 'Tahun 1969.', 'Perbezaan fahaman politik mencetuskan rusuhan kaum 13 Mei 1969.'),
(312, 3, 'Berapakah matlamat dan prinsip Rukun Negara?', 'Tiga matlamat dan lima prinsip', 'Lima matlamat dan tiga prinsip', 'Sepuluh matlamat dan sepuluh prinsip', 'Lima matlamat dan lima prinsip', 'D', 'Dua-dua lima.', 'Rukun Negara mempunyai lima matlamat dan lima prinsip.'),
(313, 3, 'Manakah ialah matlamat Rukun Negara?', 'Menambah cukai', 'Menghalang pembangunan', 'Mencapai perpaduan yang lebih erat', 'Mengurangkan kebebasan beragama', 'C', 'Matlamat pertama.', 'Matlamat pertama ialah mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat.'),
(314, 3, 'Membina masyarakat progresif yang menggunakan sains dan teknologi moden ialah matlamat ke...', 'satu', 'lima', 'dua', 'tiga', 'B', 'Ia matlamat terakhir.', 'Matlamat kelima ialah membina masyarakat progresif yang menggunakan sains dan teknologi moden.'),
(315, 3, 'Apakah prinsip pertama Rukun Negara?', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada Raja dan Negara', 'Keluhuran Perlembagaan', 'Kedaulatan Undang-undang', 'A', 'Berkaitan agama.', 'Prinsip pertama ialah Kepercayaan kepada Tuhan.'),
(316, 3, 'Siapakah Ketua Utama Negara Malaysia?', 'Perdana Menteri', 'Sultan Selangor', 'Ketua Hakim Negara', 'Yang di-Pertuan Agong', 'D', 'Pemerintah tertinggi negara.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara.'),
(317, 3, 'Apakah maksud keluhuran perlembagaan?', 'Perdana Menteri boleh mengubah undang-undang sesuka hati', 'Undang-undang hanya untuk rakyat biasa', 'Perlembagaan Persekutuan ialah undang-undang tertinggi negara', 'Perlembagaan boleh diabaikan', 'C', 'Tiada yang mengatasinya.', 'Keluhuran perlembagaan bermaksud Perlembagaan Persekutuan ialah undang-undang tertinggi.'),
(318, 3, 'Setiap rakyat perlu menghormati dan mematuhi undang-undang. Ini prinsip...', 'Kesopanan dan kesusilaan', 'Kedaulatan undang-undang', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada raja dan negara', 'B', 'Prinsip keempat.', 'Kedaulatan undang-undang bermaksud setiap rakyat menghormati dan mematuhi undang-undang.'),
(319, 3, 'Prinsip yang berperanan membentuk masyarakat untuk menghormati amalan beragama masyarakat lain ialah...', 'Kepercayaan kepada Tuhan', 'Keluhuran perlembagaan', 'Kedaulatan undang-undang', 'Kesopanan dan kesusilaan', 'A', 'Hormat amalan agama.', 'Kepercayaan kepada Tuhan melahirkan rakyat yang menghormati amalan beragama masyarakat lain.'),
(320, 3, 'Kesopanan dan kesusilaan bermaksud...', 'Hukuman bagi pesalah', 'Pelaburan asing', 'Kekayaan negara', 'Amalan nilai murni yang melambangkan keperibadian rakyat', 'D', 'Prinsip kelima.', 'Kesopanan dan kesusilaan ialah amalan nilai murni.'),
(321, 3, 'Apakah peranan Rukun Negara dalam kehidupan harian?', 'Menambah jurang kaum', 'Memisahkan agama', 'Mewujudkan rakyat bersatu padu dan bertoleransi', 'Mengurangkan cukai', 'C', 'Hubungkan dengan perpaduan.', 'Rukun Negara berperanan mewujudkan rakyat yang bersatu padu dan bersikap toleransi.'),
(322, 3, 'Manakah ialah lambang kedaulatan negara?', 'Pakaian, kasut dan beg', 'Jalur Gemilang, Jata Negara dan lagu Negaraku', 'Kereta, basikal dan motosikal', 'Rumah, kedai dan ladang', 'B', 'Bendera, jata dan lagu.', 'Rakyat patriotik menghormati Jalur Gemilang, Jata Negara dan lagu Negaraku.'),
(323, 3, 'Mengapakah rakyat perlu mematuhi undang-undang?', 'Mewujudkan keamanan dan kesejahteraan', 'Menambah jenayah', 'Mengurangkan sekolah', 'Menghentikan pembangunan', 'A', 'Fikirkan keselamatan negara.', 'Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan.'),
(324, 3, 'Apakah yang dimaksudkan dengan integriti?', 'Sikap tamak', 'Sikap malas', 'Sikap sombong', 'Sikap kejujuran yang tulen dan tidak berubah', 'D', 'Contoh: tidak meniru dalam peperiksaan.', 'Integriti bermaksud kejujuran yang tulen dan tidak berubah.'),
(325, 3, 'Manakah contoh amalan integriti?', 'Meniru supaya lulus', 'Memberi rasuah', 'Tidak meniru dalam peperiksaan', 'Menipu kawan', 'C', 'Kejujuran dalam peperiksaan.', 'Tidak meniru dalam peperiksaan ialah contoh integriti.'),
(326, 3, 'Bagaimanakah agama dapat mengelakkan keruntuhan moral?', 'Menghentikan sekolah', 'Membentuk masyarakat yang patuh ajaran agama', 'Menambah kekayaan', 'Menghalang pelajaran', 'B', 'Fikirkan nilai agama.', 'Masyarakat yang beragama dapat mengelakkan dengki, rasuah, dadah dan keruntuhan moral.'),
(327, 3, 'Mengapakah rakyat perlu menghormati budaya kaum lain?', 'Memupuk perpaduan dan toleransi', 'Supaya menang pertandingan', 'Supaya mendapat hadiah', 'Supaya diam sahaja', 'A', 'Hubungkan dengan perpaduan.', 'Rakyat dibimbing menghormati budaya kaum lain melalui Rukun Negara.'),
(328, 3, 'Rukun Negara berperanan membentuk masyarakat yang cinta akan negara. Ini disebut masyarakat...', 'pesimis', 'individualistik', 'terasing', 'patriotik', 'D', 'Cinta negara.', 'Masyarakat patriotik cinta negara, taat setia dan sanggup berkorban.'),
(329, 3, 'Seorang murid membuang sampah di tempat yang betul dan menegur rakan yang membuangnya merata-rata. Prinsip Rukun Negara yang paling ditunjukkan ialah...', 'Keluhuran Perlembagaan', 'Kesetiaan kepada Raja dan Negara', 'Kesopanan dan Kesusilaan', 'Kepercayaan kepada Tuhan', 'C', 'Fikirkan nilai murni dalam kehidupan harian.', 'Mengamalkan nilai murni dan menjaga kebersihan ialah contoh Kesopanan dan Kesusilaan.'),
(330, 3, 'Seorang anggota komando sanggup menggadai nyawa demi mempertahankan kedaulatan negara. Prinsip yang diamalkan ialah...', 'Kedaulatan Undang-undang', 'Kesetiaan kepada Raja dan Negara', 'Kesopanan dan Kesusilaan', 'Keluhuran Perlembagaan', 'B', 'Taat setia dan sanggup berkorban untuk negara.', 'Pengorbanan demi negara menunjukkan Kesetiaan kepada Raja dan Negara.'),
(331, 3, 'Seorang peguam menolak menggubal undang-undang yang bercanggah dengan Perlembagaan Persekutuan. Prinsip yang dipegangnya ialah...', 'Keluhuran Perlembagaan', 'Kepercayaan kepada Tuhan', 'Kesopanan dan Kesusilaan', 'Kesetiaan kepada Raja dan Negara', 'A', 'Perlembagaan ialah undang-undang tertinggi.', 'Perlembagaan sebagai undang-undang tertinggi menunjukkan Keluhuran Perlembagaan.'),
(332, 3, 'Mengapakah MAPEN perlu dianggotai wakil daripada pelbagai pihak semasa merangka Rukun Negara?', 'Supaya mesyuarat berlangsung lebih lama dan banyak perbincangan', 'Supaya hanya satu kaum sahaja membuat semua keputusan', 'Supaya MAGERAN tidak perlu lagi bertugas mentadbir negara', 'Supaya semua kumpulan didengar dan Rukun Negara diterima bersama', 'D', 'Fikirkan keadilan dan penerimaan semua pihak.', 'Wakil pelbagai pihak memastikan semua suara didengar, maka Rukun Negara diterima oleh seluruh masyarakat.'),
(333, 3, 'Rukun Negara diisytiharkan pada 31 Ogos 1970. Mengapakah tarikh itu bermakna?', 'Ia hari pertama MAGERAN ditubuhkan untuk mentadbir negara', 'Ia hari rusuhan 13 Mei berlaku di ibu negara', 'Ia bersempena ulang tahun Hari Kebangsaan yang ke-13 dan menegaskan perpaduan', 'Ia hari MAPEN mula bersidang buat pertama kali', 'C', 'Hubungkan dengan sambutan kemerdekaan.', 'Pengisytiharan bersempena Hari Kebangsaan ke-13 mengingatkan bahawa perpaduan ialah asas negara.'),
(334, 3, 'Dua jiran berlainan kaum jarang bertegur sapa kerana tinggal berasingan. Apakah cadangan terbaik untuk mengeratkan hubungan mereka?', 'Mengelak daripada bertemu sepanjang masa supaya tiada salah faham', 'Menyertai aktiviti gotong-royong dan sambutan perayaan bersama', 'Menukar jiran masing-masing secara paksa tanpa bertanya', 'Menunggu sahaja pihak lain menyelesaikan masalah', 'B', 'Tingkatkan peluang berinteraksi.', 'Aktiviti bersama menambah peluang berinteraksi, selaras dengan matlamat perpaduan yang lebih erat.'),
(335, 3, 'Seorang murid enggan meniru jawapan kawan walaupun peluang terbuka. Sikap ini menunjukkan...', 'Integriti', 'Rasa dengki', 'Sikap tamak', 'Sikap sombong', 'A', 'Kejujuran yang tulen dan tidak berubah.', 'Tidak meniru dalam peperiksaan ialah contoh integriti.'),
(336, 3, 'Jika rakyat tidak mematuhi undang-undang, apakah kesan yang paling mungkin berlaku?', 'Perpaduan antara kaum menjadi lebih erat', 'Kemakmuran dinikmati secara adil dan saksama', 'Jenayah akan berkurangan dengan sendirinya', 'Keamanan dan kesejahteraan masyarakat terjejas', 'D', 'Kaitkan dengan peranan menghormati undang-undang.', 'Kepatuhan undang-undang menjamin keamanan dan kesejahteraan; jika dilanggar, kedua-duanya terjejas.'),
(337, 3, 'Manakah susunan peristiwa yang betul dalam pembentukan Rukun Negara?', 'Pengisytiharan 31 Ogos 1970, rusuhan 13 Mei 1969, penubuhan jawatankuasa 4 Mac 1970', 'Penubuhan jawatankuasa 4 Mac 1970, rusuhan 13 Mei 1969, pengisytiharan 31 Ogos 1970', 'Rusuhan 13 Mei 1969, penubuhan jawatankuasa 4 Mac 1970, pengisytiharan 31 Ogos 1970', 'Rusuhan 13 Mei 1969, pengisytiharan 31 Ogos 1970, penubuhan jawatankuasa 4 Mac 1970', 'C', 'Sebab dahulu, kemudian perundingan, kemudian pengisytiharan.', 'Rusuhan mencetuskan keperluan, jawatankuasa merangka, kemudian Rukun Negara diisytiharkan.');
